// ===== l7 · Lautschule data (Mephisto 13.1, track L). Constants only — logic in v2/c_l7.js, recorder in v2/c_l7_rec.js.
// LAUT = 25 pronunciation units (speech.md §4.3, completed). Pair = [a, b, ipaA, ipaB, contrastTag, flags, ttsA, ttsB]
//   flags: "" | "h" (homophones: taught, never used in a listening test) | "n" (homographs: a voice reading the spelling cannot make the contrast)
//   ttsA/ttsB: what a voice must read when the display text is not speakable as written.
// Stress notation: the stressed syllable sits in {braces}; shown in orange, stripped before speech. "·" separates syllables in tap items.
// stress items (units 21–23): [sentence, "syl·la·bles", stressedIndex, english]; unit 24: [sentence, accentedWord, "↘"|"↗"|"→", english]
// Every unit: lv 0–4 (A1…C1), theme, no week (track I binds units to chapters).
var LAUT_ORDER=[12,2,3,4,1,7,13,14,16,20,10,11,18,15,17,19,5,6,8,9,21,22,23,24,25];
var LAUT=[
{id:"lt01",n:1,lv:0,theme:"vokale",dia:"",t:"Lange und kurze Vokale",en:"Long and short vowels",
 rule:["Ein Vokal ist lang vor einem einzelnen Konsonanten (Blut), vor h (Zahn), wenn er doppelt geschrieben ist (Beet, Staat) und in ie (Fieber). Vor zwei Konsonanten ist er meist kurz (Bett, Stadt). Kurze Vokale sind außerdem offener und lockerer.","A vowel is long before a single consonant (Blut), before h (Zahn), when doubled (Beet, Staat) and in ie (Fieber). Before two consonants it is usually short (Bett, Stadt). Short vowels are also more open and lax."],
 trap:{ar:["Arabisch kennt lange und kurze Vokale – aber nicht den Klangwechsel. Das kurze i in Mitte ist offener als das lange i in Miete. Halten Sie kurze Vokale kurz und offen.","Arabic has long and short vowels, but not the change of quality: the short i of Mitte is more open than the long i of Miete. Keep short vowels short and open."],
       en:["Englische Sprecher lassen lange Vokale gleiten (Beet klingt wie „bayt“). Deutsche lange Vokale bleiben ruhig und rein.","English speakers glide long vowels (Beet sounds like 'bayt'). German long vowels stay steady and pure."]},
 art:["Halten Sie lange Vokale ruhig und gespannt, ohne Gleiten. Kurze Vokale sind kurz und locker: Der Mund ist etwas weiter offen, die Zunge entspannter. Klatschen Sie mit: lang = ein gehaltener Ton, kurz = ein Klatschen.","Hold long vowels steady and tense, without a glide. Short vowels are short and lax: the mouth a little more open, the tongue more relaxed. Clap along: long = one held note, short = one clap."],
 pairs:[["Miete","Mitte","ˈmiːtə","ˈmɪtə","i"],["Staat","Stadt","ʃtaːt","ʃtat","a"],["Ofen","offen","ˈoːfn̩","ˈɔfn̩","o"],["fühlen","füllen","ˈfyːlən","ˈfʏlən","ü"],["Höhle","Hölle","ˈhøːlə","ˈhœlə","ö"],["Beet","Bett","beːt","bɛt","e"],["Hüte","Hütte","ˈhyːtə","ˈhʏtə","ü"],["Polen","Pollen","ˈpoːlən","ˈpɔlən","o"],["Ruhm","Rum","ʁuːm","ʁʊm","u"],["Wahn","wann","vaːn","van","a"],["ihn","in","iːn","ɪn","i"],["Mus","muss","muːs","mʊs","u"],["Saat","satt","zaːt","zat","a"]],
 words:["Blut","Puls","Bett","Fieber","Magen","Wasser","Sohn","Rücken"],
 sent:[["Der Patient liegt im Bett, nicht im Beet.","The patient is lying in bed, not in the flowerbed."],["Sie fühlen den Puls, dann füllen Sie den Bogen aus.","You feel the pulse, then you fill in the form."],["Wann haben Sie zuletzt etwas getrunken?","When did you last drink something?"]],
 self:[["Ist das a in Staat deutlich länger als in Stadt?","Is the a in Staat clearly longer than in Stadt?"],["Klingt Ihr kurzes i in Mitte offener als das lange i in Miete?","Does your short i in Mitte sound more open than the long i in Miete?"]],
 meph:["Bett, nicht Beet. Ihre Patienten danken es Ihnen – sie wollten nie im Gemüse liegen.","Bed, not flowerbed. Your patients thank you – they never wanted to lie among the vegetables."]},

{id:"lt02",n:2,lv:0,theme:"vokale",dia:"rund",t:"ü gegen u und i",en:"ü vs u and i",
 rule:["ü hat die Zunge von i und die Lippen von u. Lang in Tür, Übelkeit, kurz in Rücken, fünf.","ü has the tongue of i and the lips of u. Long in Tür, Übelkeit, short in Rücken, fünf."],
 trap:{ar:["Arabisch hat kein ü. Es wird oft zu u oder i – und das Wort ändert sich: Mütter wird Mutter, Tür wird Tier.","Arabic has no ü. It often becomes u or i – and the word changes: Mütter becomes Mutter, Tür becomes Tier."],
       en:["Englisch hat kein ü. Ersetzen Sie es nicht durch „you“ oder „ee“.","English has no ü. Do not replace it with 'you' or 'ee'."]},
 art:["Sagen Sie ein langes iiii. Halten Sie die Zunge ganz still und runden Sie die Lippen langsam zu einem Kussmund – es wird üüüü. Prüfen Sie im Spiegel: Lippen vorn und rund, Zunge vorn und hoch.","Say a long iiii. Keep the tongue completely still and slowly round the lips into a kiss – it becomes üüüü. Check in a mirror: lips forward and round, tongue high and front."],
 pairs:[["Mutter","Mütter","ˈmʊtɐ","ˈmʏtɐ","u-ü"],["Bruder","Brüder","ˈbʁuːdɐ","ˈbʁyːdɐ","u-ü"],["Kuchen","Küchen","ˈkuːxn̩","ˈkʏçn̩","u-ü"],["Tier","Tür","tiːɐ̯","tyːɐ̯","i-ü"],["Kiste","Küste","ˈkɪstə","ˈkʏstə","i-ü"],["vier","für","fiːɐ̯","fyːɐ̯","i-ü"],["Fuß","Füße","fuːs","ˈfyːsə","u-ü"],["drucken","drücken","ˈdʁʊkn̩","ˈdʁʏkn̩","u-ü"],["Kissen","küssen","ˈkɪsn̩","ˈkʏsn̩","i-ü"],["spielen","spülen","ˈʃpiːlən","ˈʃpyːlən","i-ü"],["Liege","Lüge","ˈliːɡə","ˈlyːɡə","i-ü"],["Zug","Züge","tsuːk","ˈtsyːɡə","u-ü"]],
 words:["Übelkeit","müde","Rücken","Frühstück","Gefühl","Überweisung","Schüttelfrost","fünf"],
 sent:[["Drücken Sie bitte hier – tut das weh?","Please press here – does that hurt?"],["Die Übelkeit kam nach dem Frühstück.","The nausea came after breakfast."],["Sind Sie nur müde, oder haben Sie Schüttelfrost?","Are you just tired, or do you have chills?"]],
 self:[["Bleibt Ihre Zunge bei ü so weit vorn wie bei i?","Does your tongue stay as far forward for ü as for i?"],["Sind Ihre Lippen bei ü rund und vorgeschoben?","Are your lips round and pushed forward for ü?"]],
 meph:["Tür, nicht Tier. Ein Tier hätte ich Ihnen ohnehin nicht anvertraut.","Door, not animal. I would never have trusted you with an animal anyway."]},

{id:"lt03",n:3,lv:0,theme:"vokale",dia:"rund",t:"ö gegen o und e",en:"ö vs o and e",
 rule:["ö hat die Zunge von e und die Lippen von o. Lang in schön, Ödem, kurz in können, Röntgen.","ö has the tongue of e and the lips of o. Long in schön, Ödem, short in können, Röntgen."],
 trap:{ar:["Ohne ö im Arabischen wird es zu o oder e: schön klingt wie schon, können wie kennen.","Arabic has no ö, so it turns into o or e: schön sounds like schon, können like kennen."],
       en:["Das britische „er“ in her ist nah, aber zu offen und ohne runde Lippen. Runden Sie!","The British 'er' in her is close, but too open and with spread lips. Round them!"]},
 art:["Sagen Sie eeee wie in See. Die Zunge bleibt, die Lippen runden sich wie bei o: Es wird öööö. Das kurze ö (können) ist offener – Mund etwas weiter auf, Lippen trotzdem rund.","Say eeee as in See. The tongue stays, the lips round as for o: it becomes öööö. The short ö (können) is more open – mouth a little wider, lips still round."],
 pairs:[["schon","schön","ʃoːn","ʃøːn","o-ö"],["Ofen","Öfen","ˈoːfn̩","ˈøːfn̩","o-ö"],["Tochter","Töchter","ˈtɔxtɐ","ˈtœçtɐ","o-ö"],["lesen","lösen","ˈleːzn̩","ˈløːzn̩","e-ö"],["kennen","können","ˈkɛnən","ˈkœnən","e-ö"],["Sehne","Söhne","ˈzeːnə","ˈzøːnə","e-ö"],["Hölle","helle","ˈhœlə","ˈhɛlə","e-ö"],["Ton","Töne","toːn","ˈtøːnə","o-ö"],["Bogen","Bögen","ˈboːɡn̩","ˈbøːɡn̩","o-ö"],["Meere","Möhre","ˈmeːʁə","ˈmøːʁə","e-ö"],["Hefe","Höfe","ˈheːfə","ˈhøːfə","e-ö"],["Rock","Röcke","ʁɔk","ˈʁœkə","o-ö"]],
 words:["Röntgen","Knöchel","Ödem","hören","Löffel","möchten","Störung","Öffnung"],
 sent:[["Können Sie die Hand öffnen?","Can you open your hand?"],["Wir röntgen den Knöchel.","We are going to X-ray the ankle."],["Die Töchter möchten den Oberarzt sprechen.","The daughters would like to speak to the consultant."]],
 self:[["Klingt Ihr schön anders als schon – nicht nur länger?","Does your schön sound different from schon – not just longer?"],["Sind die Lippen bei können rund?","Are your lips round for können?"]],
 meph:["Schön. Nicht schon – schön. Endlich ein Wort von Ihnen, das ich glaube.","Schön. Not schon – schön. At last a word from you that I believe."]},

{id:"lt04",n:4,lv:0,theme:"vokale",dia:"",t:"e gegen i",en:"e vs i (no diphthong)",
 rule:["Langes e (legen, Leber) ist ein reiner, gespannter Vokal zwischen i und ä. Langes i (liegen, Fieber) liegt höher. Kurzes e (Bett) ist offen wie in englisch bed.","Long e (legen, Leber) is a pure, tense vowel between i and ä. Long i (liegen, Fieber) is higher. Short e (Bett) is open as in English bed."],
 trap:{ar:["Arabisch hat nur a, i, u. e und i fallen leicht zusammen – liegen und legen klingen dann gleich.","Arabic has only a, i, u. e and i easily merge – liegen and legen then sound the same."],
       en:["Englisch macht aus langem e ein „ay“ (Tee wie „tay“). Das deutsche e gleitet nicht.","English turns long e into 'ay' (Tee like 'tay'). German e does not glide."]},
 art:["Für langes e lächeln Sie leicht, die Zunge ist hoch und vorn, aber etwas tiefer als bei i – und Sie halten den Laut, ohne zu gleiten. Für i heben Sie die Zunge noch etwas höher und spannen sie an.","For long e smile slightly, tongue high and front but a little lower than for i – and hold the sound without gliding. For i raise the tongue a little higher and tense it."],
 pairs:[["bieten","beten","ˈbiːtn̩","ˈbeːtn̩","i-e"],["liegen","legen","ˈliːɡn̩","ˈleːɡn̩","i-e"],["Wirt","Wert","vɪʁt","veːɐ̯t","i-e"],["bitten","betten","ˈbɪtn̩","ˈbɛtn̩","i-e"],["wir","wer","viːɐ̯","veːɐ̯","i-e"],["dir","der","diːɐ̯","deːɐ̯","i-e"],["sitzen","setzen","ˈzɪtsn̩","ˈzɛtsn̩","i-e"],["ist","esst","ɪst","ɛst","i-e"],["Lieder","Leder","ˈliːdɐ","ˈleːdɐ","i-e"],["fielen","fehlen","ˈfiːlən","ˈfeːlən","i-e"],["Wiege","Wege","ˈviːɡə","ˈveːɡə","i-e"]],
 words:["Leber","Becken","sehen","Gewebe","Termin","Tee","Medikament","Schmerz"],
 sent:[["Legen Sie sich hin – bleiben Sie liegen.","Lie down – stay lying down."],["Bitte setzen Sie sich; wie lange sitzen Sie schon hier?","Please take a seat; how long have you been sitting here?"],["Nehmen Sie die Tablette nicht mit Milch.","Do not take the tablet with milk."]],
 self:[["Klingt Ihr legen anders als liegen?","Does your legen sound different from liegen?"],["Bleibt das e in Tee ruhig, ohne „ay“?","Does the e in Tee stay steady, without 'ay'?"]],
 meph:["Legen, liegen – Sie haben den Unterschied gefunden. Ihre Patienten bleiben jetzt dort, wo Sie sie hinlegen.","Legen, liegen – you found the difference. Your patients now stay where you put them."]},

{id:"lt05",n:5,lv:0,theme:"vokale",dia:"",t:"o gegen u",en:"o vs u",
 rule:["Langes o (oben, Ohr) ist rund und offener als langes u (Blut, Ruhe). Kurzes o (Kopf) und kurzes u (Mund) sind noch offener.","Long o (oben, Ohr) is round and more open than long u (Blut, Ruhe). Short o (Kopf) and short u (Mund) are more open still."],
 trap:{ar:["Arabisch hat kein eigenes o – o und u fallen zusammen: Mund wird Mond.","Arabic has no separate o – o and u merge: Mund becomes Mond."],
       en:["Englisch lässt langes o gleiten („oh-oo“). Halten Sie es rein.","English glides long o ('oh-oo'). Keep it pure."]},
 art:["Bei o sind die Lippen rund, aber weiter offen als bei u; die Zunge liegt etwas tiefer. Bei u sind die Lippen eng und vorgestülpt, wie zum Pfeifen. Wechseln Sie langsam: uuu – ooo – uuu.","For o the lips are round but more open than for u; the tongue sits a little lower. For u the lips are tight and pushed out, as if to whistle. Alternate slowly: uuu – ooo – uuu."],
 pairs:[["Mus","Moos","muːs","moːs","u-o"],["Schuss","Schoss","ʃʊs","ʃɔs","u-o"],["Ruhe","rohe","ˈʁuːə","ˈʁoːə","u-o"],["Bus","Boss","bʊs","bɔs","u-o"],["Mund","Mond","mʊnt","moːnt","u-o"],["Buden","Boden","ˈbuːdn̩","ˈboːdn̩","u-o"],["Luft","Loft","lʊft","lɔft","u-o"],["Huhn","Hohn","huːn","hoːn","u-o"],["Ruhm","Rom","ʁuːm","ʁoːm","u-o"],["Flug","flog","fluːk","floːk","u-o"],["Gruß","groß","ɡʁuːs","ɡʁoːs","u-o"],["dumm","Dom","dʊm","doːm","u-o"]],
 words:["oben","unten","Husten","Kopf","Blut","Ohr","Ultraschall","Notfall"],
 sent:[["Der Mund ist trocken.","The mouth is dry."],["Wo tut es weh – unten oder oben?","Where does it hurt – below or above?"],["Schlucken Sie in Ruhe, ohne zu husten.","Swallow calmly, without coughing."]],
 self:[["Ist Ihr Mund bei Mond weiter offen als bei Mund?","Is your mouth more open for Mond than for Mund?"],["Gleitet Ihr langes o am Ende zu u?","Does your long o glide to u at the end?"]],
 meph:["Mund und Mond. Gut – Sie schauen dem Patienten jetzt in den Hals statt in den Himmel.","Mouth and moon. Good – now you look down the patient's throat instead of at the sky."]},

{id:"lt06",n:6,lv:0,theme:"vokale",dia:"",t:"ei, ie, eu/äu, au und ä",en:"Diphthongs ei, ie, eu/äu, au and ä",
 rule:["ei und ai = [aɪ] (mein, Mai), ie = langes [iː] (Fieber), eu und äu = [ɔʏ] (heute, Häute – gleicher Laut), au = [aʊ] (Bauch). Langes ä (Bären) ist offener als langes e (Beeren).","ei and ai = [aɪ] (mein, Mai), ie = long [iː] (Fieber), eu and äu = [ɔʏ] (heute, Häute – the same sound), au = [aʊ] (Bauch). Long ä (Bären) is more open than long e (Beeren)."],
 trap:{ar:["eu/äu gibt es im Arabischen nicht: Beginnen Sie mit runden Lippen (o) und gleiten Sie zu ü. Langes ä wird leicht zu e.","eu/äu does not exist in Arabic: start with round lips (o) and glide to ü. Long ä easily turns into e."],
       en:["Englisch liest ei als „ee“ und ie als „eye“ – genau verkehrt herum. Merkhilfe: Sprechen Sie den englischen Namen des zweiten Buchstabens: ie → „ee“, ei → „eye“.","English reads ei as 'ee' and ie as 'eye' – exactly backwards. Memory aid: say the English name of the second letter: ie → 'ee', ei → 'eye'."]},
 art:["Ein Diphthong ist eine Gleitbewegung. Bei ei beginnt der Mund weit offen (a) und schließt sich zum i. Bei eu/äu beginnen die Lippen rund (o) und gleiten zu ü; bei au gleitet der Mund von a zu u.","A diphthong is a gliding movement. For ei the mouth starts wide open (a) and closes towards i. For eu/äu the lips start round (o) and glide towards ü; for au the mouth glides from a to u."],
 pairs:[["Wein","Wien","vaɪ̯n","viːn","ei-ie"],["Leid","Lied","laɪ̯t","liːt","ei-ie"],["reisen","Riesen","ˈʁaɪ̯zn̩","ˈʁiːzn̩","ei-ie"],["schreiben","schrieben","ˈʃʁaɪ̯bn̩","ˈʃʁiːbn̩","ei-ie"],["Feuer","Feier","ˈfɔʏ̯ɐ","ˈfaɪ̯ɐ","eu-ei"],["Eule","Eile","ˈɔʏ̯lə","ˈaɪ̯lə","eu-ei"],["Leute","Laute","ˈlɔʏ̯tə","ˈlaʊ̯tə","eu-au"],["Bären","Beeren","ˈbɛːʁən","ˈbeːʁən","ä-e"],["Raum","Reim","ʁaʊ̯m","ʁaɪ̯m","au-ei"],["Ehre","Ähre","ˈeːʁə","ˈɛːʁə","ä-e"],["Säule","Seile","ˈzɔʏ̯lə","ˈzaɪ̯lə","eu-ei"]],
 words:["heiß","Leiste","Niere","heute","Bauch","Kreislauf","Häufigkeit","Eiter"],
 sent:[["Die Leiste ist frei, die Niere liegt tief.","The groin is clear, the kidney lies deep."],["Seit heute früh tut der Bauch weh.","The stomach has been hurting since early this morning."],["Bleiben Sie bitte liegen, ich schreibe Ihnen etwas auf.","Please stay lying down, I will write something down for you."]],
 self:[["Klingt Ihr Wein wie „Wain“ und Ihr Wien wie „Wiin“?","Does your Wein sound like 'Wine' and your Wien like 'Veen'?"],["Beginnt heute bei Ihnen mit runden Lippen?","Does your heute start with round lips?"]],
 meph:["Wein und Wien. Den Wein verschreibe ich Ihnen nicht – die Reise vielleicht.","Wine and Vienna. I will not prescribe you the wine – the journey, perhaps."]},

{id:"lt07",n:7,lv:0,theme:"konsonanten",dia:"ich",t:"Der ich-Laut [ç]",en:"The ich sound [ç]",
 rule:["Nach e, i, ä, ö, ü, ei, eu, nach l, n, r, in der Endung -chen und in -ig am Wortende spricht man den ich-Laut [ç]: ich, Milch, durch, Mädchen, wichtig.","After e, i, ä, ö, ü, ei, eu, after l, n, r, in the ending -chen and in final -ig you say the ich sound [ç]: ich, Milch, durch, Mädchen, wichtig."],
 trap:{ar:["Der ich-Laut ist weder ش noch خ. Mit ش wird mich zu misch, mit خ klingt er hart und kratzig.","The ich sound is neither ش nor خ. With ش mich becomes misch; with خ it sounds harsh and scraping."],
       en:["Englisch ersetzt ihn durch k oder sh („ik“, „ish“). Beides ändert das Wort.","English replaces it with k or sh ('ik', 'ish'). Both change the word."]},
 art:["Sagen Sie das j von ja und flüstern Sie es mit viel Luft – das ist [ç]. Die Zungenspitze liegt hinter den unteren Zähnen, der vordere Zungenrücken nähert sich dem harten Gaumen. Die Lippen bleiben breit, nicht rund wie bei sch.","Say the y of 'yes' and whisper it with lots of air – that is [ç]. The tongue tip rests behind the lower teeth, the front of the tongue approaches the hard palate. The lips stay spread, not rounded as for sh."],
 pairs:[["Kirche","Kirsche","ˈkɪʁçə","ˈkɪʁʃə","ç-ʃ"],["Fichte","fischte","ˈfɪçtə","ˈfɪʃtə","ç-ʃ"],["mich","misch","mɪç","mɪʃ","ç-ʃ"],["Löcher","Löscher","ˈlœçɐ","ˈlœʃɐ","ç-ʃ"],["Männchen","Menschen","ˈmɛnçən","ˈmɛnʃn̩","ç-ʃ"],["welche","Wäsche","ˈvɛlçə","ˈvɛʃə","ç-ʃ"],["Stich","Stick","ʃtɪç","ʃtɪk","ç-k"],["Becher","Bäcker","ˈbɛçɐ","ˈbɛkɐ","ç-k"],["nicht","nickt","nɪçt","nɪkt","ç-k"],["dich","Tisch","dɪç","tɪʃ","ç-ʃ"],["Milch","Milz","mɪlç","mɪlts","ç-ts"]],
 words:["ich","wichtig","zwanzig","Milch","durch","Gesicht","Bronchien","leicht"],
 sent:[["Ich möchte Sie gründlich untersuchen.","I would like to examine you thoroughly."],["Ist der Stich in der Brust leicht oder heftig?","Is the stabbing pain in the chest mild or severe?"],["Sprechen Sie bitte etwas deutlicher.","Please speak a little more clearly."]],
 self:[["Sind Ihre Lippen bei ich breit (nicht rund wie bei sch)?","Are your lips spread for ich (not round as for sch)?"],["Hört man bei Milch Luft statt eines k?","Can you hear air rather than a k in Milch?"]],
 meph:["Ich. Nicht isch, nicht ick. Sie existieren jetzt auch phonetisch.","Ich. Not 'isch', not 'ick'. You now exist phonetically as well."]},

{id:"lt08",n:8,lv:0,theme:"konsonanten",dia:"ach",t:"Der ach-Laut [x]",en:"The ach sound [x]",
 rule:["Nach a, o, u und au spricht man den ach-Laut [x] hinten im Mund: Nacht, Loch, Buch, Bauch. Wird der Vokal zum Umlaut, wird daraus der ich-Laut: Buch – Bücher, Bauch – Bäuche.","After a, o, u and au you say the ach sound [x] at the back of the mouth: Nacht, Loch, Buch, Bauch. When the vowel becomes an umlaut it turns into the ich sound: Buch – Bücher, Bauch – Bäuche."],
 trap:{ar:["Das ist خ – Sie besitzen es schon. Aber das deutsche [x] ist weicher und kratzt weniger. Und nie nach i, e, ä, ö, ü!","This is خ – you already own it. But German [x] is softer and scrapes less. And never after i, e, ä, ö, ü!"],
       en:["Englisch macht daraus k (Bauk) oder h. Lassen Sie die Luft reiben.","English turns it into k (Bauk) or h. Let the air rub."]},
 art:["Der hintere Zungenrücken nähert sich dem weichen Gaumen, die Luft reibt hörbar durch die Enge. Weniger Druck als beim arabischen خ: ein Hauch, kein Kratzen.","The back of the tongue approaches the soft palate, and the air rubs audibly through the narrow gap. Less pressure than Arabic خ: a breath, not a scrape."],
 pairs:[["Nacht","nicht","naxt","nɪçt","x-ç"],["Buch","Bücher","buːx","ˈbyːçɐ","x-ç"],["Loch","Löcher","lɔx","ˈlœçɐ","x-ç"],["Bauch","Bäuche","baʊ̯x","ˈbɔʏ̯çə","x-ç"],["Dach","Dächer","dax","ˈdɛçɐ","x-ç"],["acht","echt","axt","ɛçt","x-ç"],["Nacht","nackt","naxt","nakt","x-k"],["lachen","Laken","ˈlaxn̩","ˈlaːkn̩","x-k"],["Tuch","Tücher","tuːx","ˈtyːçɐ","x-ç"],["Koch","Köche","kɔx","ˈkœçə","x-ç"],["Sucht","Süchte","zʊxt","ˈzʏçtə","x-ç"],["machen","Macken","ˈmaxn̩","ˈmakn̩","x-k"]],
 words:["Bauch","acht","Woche","Nacht","rauchen","Knochen","Schlauch","Verdacht"],
 sent:[["Der Bauch ist nachts hart.","The abdomen is hard at night."],["Seit acht Wochen husten Sie – auch nach dem Rauchen?","You have been coughing for eight weeks – also after smoking?"],["Wir haben den Verdacht auf einen Knochenbruch.","We suspect a fracture."]],
 self:[["Ist Ihr ach weich wie ein Hauch, nicht kratzig?","Is your ach soft like a breath, not scraping?"],["Wechseln Sie bei Bücher richtig zum ich-Laut?","Do you switch correctly to the ich sound in Bücher?"]],
 meph:["Acht, nicht echt – obwohl Ihre Mühe echt war. Ich bin beinahe gerührt.","Eight, not real – although your effort was real. I am almost touched."]},

{id:"lt09",n:9,lv:0,theme:"konsonanten",dia:"r",t:"Das r am Anfang",en:"Initial and prevocalic r",
 rule:["Am Wort- und Silbenanfang und nach Konsonanten (Rippe, Brust, sprechen) spricht man meist ein Reibe-r hinten am Zäpfchen [ʁ]. Ein Zungenspitzen-r [r] ist auch korrekt und im Süden häufig; das englische r ist es nicht.","At the start of words and syllables and after consonants (Rippe, Brust, sprechen) German usually has a back r at the uvula [ʁ]. A tongue-tip r [r] is correct too and common in the south; the English r is not."],
 trap:{ar:["Das gerollte ر ist verständlich und erlaubt. Das hintere r liegt nahe an einem sehr weichen غ – nicht kratzen.","The rolled ر is understood and allowed. The back r is close to a very soft غ – do not scrape."],
       en:["Das englische r (Zunge gebogen, nichts reibt) klingt im Deutschen sofort fremd. Vermeiden Sie es.","The English r (curled tongue, no friction) sounds foreign in German at once. Avoid it."]},
 art:["Gurgeln Sie ohne Wasser: Der hintere Zungenrücken nähert sich dem Zäpfchen, die Luft reibt leise. Viel weicher als غ – eher ein stimmhaftes ach. Die Zungenspitze bleibt unten hinter den Zähnen.","Gargle without water: the back of the tongue approaches the uvula, the air rubs softly. Much softer than غ – more like a voiced ach. The tongue tip stays down behind the teeth."],
 pairs:[["Rippe","Lippe","ˈʁɪpə","ˈlɪpə","r-l"],["Rücken","Lücken","ˈʁʏkn̩","ˈlʏkn̩","r-l"],["Rand","Land","ʁant","lant","r-l"],["Reise","leise","ˈʁaɪ̯zə","ˈlaɪ̯zə","r-l"],["Rand","Hand","ʁant","hant","r-h"],["Kragen","klagen","ˈkʁaːɡn̩","ˈklaːɡn̩","r-l"],["Frau","flau","fʁaʊ̯","flaʊ̯","r-l"],["Rasen","lasen","ˈʁaːzn̩","ˈlaːzn̩","r-l"],["rot","Lot","ʁoːt","loːt","r-l"],["Reis","Eis","ʁaɪ̯s","ʔaɪ̯s","r-0"],["Rose","lose","ˈʁoːzə","ˈloːzə","r-l"]],
 words:["Rippe","Rücken","Röntgen","Rezept","fragen","sprechen","Brust","Krankheit"],
 sent:[["Der Rücken brennt rechts unter der Rippe.","The back burns on the right below the rib."],["Bringen Sie bitte das Röntgenbild und das Rezept.","Please bring the X-ray and the prescription."],["Ist Ihnen flau, oder haben Sie Brustschmerzen?","Do you feel queasy, or do you have chest pain?"]],
 self:[["Liegt Ihre Zungenspitze beim r unten – oder ist sie gebogen wie im Englischen?","Does your tongue tip stay down for r – or is it curled as in English?"],["Klingt Ihr r weich, nicht kratzig?","Does your r sound soft, not scraping?"]],
 meph:["Rippe, nicht Lippe. Der Chirurg dankt – er hätte sonst am falschen Ende geschnitten.","Rib, not lip. The surgeon thanks you – otherwise he would have cut at the wrong end."]},

{id:"lt10",n:10,lv:0,theme:"konsonanten",dia:"r",t:"Das vokalische r [ɐ]",en:"Vocalised r [ɐ]",
 rule:["Nach langem Vokal und in -er, er-, ver-, zer- wird r zu einem kurzen, offenen a-Laut [ɐ]: Fieber ≈ „Fieba“, Uhr ≈ „Uha“. Folgt ein Vokal, kommt das r zurück: Tier – Tiere, Ohr – Ohren.","After a long vowel and in -er, er-, ver-, zer- the r becomes a short, open a-like sound [ɐ]: Fieber ≈ 'Feeba', Uhr ≈ 'Ooa'. When a vowel follows, the r comes back: Tier – Tiere, Ohr – Ohren."],
 trap:{ar:["Jedes geschriebene r zu rollen (Fie-berr) klingt fremd und langsam. Am Silbenende verschwindet das r im Deutschen.","Rolling every written r (Fie-berr) sounds foreign and slow. At the end of a syllable the German r disappears."],
       en:["Britisches Englisch ohne r (water) ist hier nah dran. Amerikanisches r-Färben vermeiden.","Non-rhotic British English (water) is close. Avoid the American r-colour."]},
 art:["Sagen Sie am Ende von -er kein r, sondern ein kurzes, entspanntes a – der Mund ist halb offen, die Zunge liegt flach. bitte (Schwa, Mund fast zu) und bitter (ɐ, Mund weiter offen) müssen verschieden klingen.","At the end of -er say no r but a short, relaxed a – mouth half open, tongue flat. bitte (schwa, mouth nearly closed) and bitter (ɐ, mouth more open) must sound different."],
 pairs:[["Lehre","Lehrer","ˈleːʁə","ˈleːʁɐ","ə-ɐ"],["bitte","bitter","ˈbɪtə","ˈbɪtɐ","ə-ɐ"],["Ehre","eher","ˈeːʁə","ˈeːɐ","ə-ɐ"],["diese","dieser","ˈdiːzə","ˈdiːzɐ","ə-ɐ"],["Tier","Tiere","tiːɐ̯","ˈtiːʁə","ɐ-ʁ"],["Uhr","Uhren","uːɐ̯","ˈuːʁən","ɐ-ʁ"],["Ohr","Ohren","oːɐ̯","ˈoːʁən","ɐ-ʁ"],["Messe","Messer","ˈmɛsə","ˈmɛsɐ","ə-ɐ"],["Lage","Lager","ˈlaːɡə","ˈlaːɡɐ","ə-ɐ"],["Wunde","Wunder","ˈvʊndə","ˈvʊndɐ","ə-ɐ"],["Liebe","lieber","ˈliːbə","ˈliːbɐ","ə-ɐ"]],
 words:["Fieber","Vater","Wasser","Schwester","Leber","Ohr","Arzt","verletzt"],
 sent:[["Der Vater der Schwester hat hohes Fieber.","The sister's father has a high fever."],["Wir untersuchen Ihr Ohr um vier Uhr.","We will examine your ear at four o'clock."],["Die Wunde ist sauber, aber der Verband muss gewechselt werden.","The wound is clean, but the dressing needs changing."]],
 self:[["Klingt das Ende von Fieber wie ein kurzes a – ohne r?","Does the end of Fieber sound like a short a – without r?"],["Klingen bitte und bitter bei Ihnen verschieden?","Do bitte and bitter sound different when you say them?"]],
 meph:["Fieber, nicht Fieberrr. Sie klingen nicht mehr wie ein Motor, der anspringt.","Fieber, not 'Fieberrr'. You no longer sound like an engine starting."]},

{id:"lt11",n:11,lv:0,theme:"konsonanten",dia:"",t:"Auslautverhärtung",en:"Final devoicing",
 rule:["Am Silben- und Wortende werden b, d, g, v, s stimmlos: [p, t, k, f, s]. Kind klingt wie „Kint“, Tag wie „Tak“. Kommt ein Vokal dazu, ist die Stimme wieder da: Kin-der, Ta-ge.","At the end of a syllable or word, b, d, g, v, s lose their voice: [p, t, k, f, s]. Kind sounds like 'Kint', Tag like 'Tak'. When a vowel follows, the voice comes back: Kin-der, Ta-ge."],
 trap:{ar:["Arabisch spricht ب und د am Ende stimmhaft; Deutsch nicht. Ein stimmhaftes d in Kind klingt fremd.","Arabic keeps final ب and د voiced; German does not. A voiced d in Kind sounds foreign."],
       en:["Englisch unterscheidet bad und bat. Im Deutschen klingen Rad und Rat gleich.","English distinguishes bad and bat. In German Rad and Rat sound the same."]},
 art:["Legen Sie zwei Finger an den Kehlkopf. Bei Kinder spüren Sie beim d ein Summen; bei Kind am Ende nicht – die Stimme ist schon aus. Sprechen Sie das Ende hart und kurz.","Put two fingers on your larynx. In Kinder you feel a buzz on the d; at the end of Kind you do not – the voice is already off. Say the end hard and short."],
 pairs:[["Tag","Tage","taːk","ˈtaːɡə","k-g"],["Kind","Kinder","kɪnt","ˈkɪndɐ","t-d"],["Hand","Hände","hant","ˈhɛndə","t-d"],["gelb","gelbe","ɡɛlp","ˈɡɛlbə","p-b"],["Rad","Rat","ʁaːt","ʁaːt","gleich","h"],["Bund","bunt","bʊnt","bʊnt","gleich","h"],["Weg","weg","veːk","vɛk","lang-kurz"],["Urlaub","Urlaube","ˈuːɐ̯laʊ̯p","ˈuːɐ̯laʊ̯bə","p-b"],["Dieb","Diebe","diːp","ˈdiːbə","p-b"],["Bad","baden","baːt","ˈbaːdn̩","t-d"],["Berg","Berge","bɛʁk","ˈbɛʁɡə","k-g"],["Haus","Häuser","haʊ̯s","ˈhɔʏ̯zɐ","s-z"],["Befund","Befunde","bəˈfʊnt","bəˈfʊndə","t-d"],["Lied","Lid","liːt","liːt","gleich","h"]],
 words:["Tag","Kind","Hand","Hals","Stuhlgang","Befund","Urlaub","Verband"],
 sent:[["Der Befund ist gut.","The finding is fine."],["Das Kind hat seit Montag Durchfall.","The child has had diarrhoea since Monday."],["Guten Tag – Ihre Hand, bitte.","Good afternoon – your hand, please."]],
 self:[["Spüren Sie am Ende von Kind kein Summen im Hals mehr?","At the end of Kind, is the buzz in your throat gone?"],["Kommt die Stimme in Kinder beim d zurück?","Does the voice return on the d of Kinder?"]],
 meph:["Kind mit hartem t. Klingt kalt? So ist Deutsch. Sie gewöhnen sich daran – wie an mich.","Kind with a hard t. Sounds cold? That is German. You will get used to it – as you got used to me."]},

{id:"lt12",n:12,lv:0,theme:"konsonanten",dia:"pb",t:"p, t, k und b, d, g",en:"Aspiration: p t k vs b d g",
 rule:["p, t, k am Anfang einer betonten Silbe sind behaucht: Nach dem Verschluss kommt ein kleiner Luftstoß. b, d, g haben keinen Hauch. Nach sch (sp, st) fällt der Hauch weg.","p, t, k at the start of a stressed syllable are aspirated: a small puff of air follows the release. b, d, g have no puff. After sch (sp, st) the puff disappears."],
 trap:{ar:["Arabisch hat kein /p/. Aus Puls wird „Buls“, aus Patient „Batient“, aus Probe „Brobe“ – und der Patient versteht Bus.","Arabic has no /p/. Puls becomes 'Buls', Patient 'Batient', Probe 'Brobe' – and the patient hears 'bus'."],
       en:["Englisch behaucht p, t, k ebenfalls – nur stärker auch in der Wortmitte behalten (Tablette, Kapsel).","English aspirates p, t, k too – keep the puff in the middle of words as well (Tablette, Kapsel)."]},
 art:["Halten Sie ein Blatt Papier vor den Mund. Bei Puls muss es sich bewegen; bei Bus bewegt es sich nicht. Lippen fest schließen, Luft stauen, dann mit einem Hauch öffnen – die Stimme beginnt erst nach dem Hauch.","Hold a sheet of paper in front of your mouth. On Puls it must move; on Bus it does not. Close the lips firmly, build up air, then open with a puff – the voice starts only after the puff."],
 pairs:[["Paar","Bar","paːɐ̯","baːɐ̯","p-b"],["packen","backen","ˈpakn̩","ˈbakn̩","p-b"],["Pein","Bein","paɪ̯n","baɪ̯n","p-b"],["Pass","Bass","pas","bas","p-b"],["Oper","Ober","ˈoːpɐ","ˈoːbɐ","p-b"],["Gepäck","Gebäck","ɡəˈpɛk","ɡəˈbɛk","p-b"],["Rippe","Robbe","ˈʁɪpə","ˈʁɔbə","p-b"],["Prise","Brise","ˈpʁiːzə","ˈbʁiːzə","p-b"],["Polen","Bohlen","ˈpoːlən","ˈboːlən","p-b"],["Tank","Dank","taŋk","daŋk","t-d"],["Kabel","Gabel","ˈkaːbl̩","ˈɡaːbl̩","k-g"],["Torf","Dorf","tɔʁf","dɔʁf","t-d"],["Karten","Garten","ˈkaʁtn̩","ˈɡaʁtn̩","k-g"]],
 words:["Puls","Patient","Probe","Pflaster","Pupille","Tablette","Kapsel","Pumpe"],
 sent:[["Der Puls des Patienten ist stabil.","The patient's pulse is stable."],["Kleben Sie das Pflaster bitte auf das Bein.","Please stick the plaster on the leg."],["Nehmen Sie eine Tablette und eine Kapsel nach dem Essen.","Take one tablet and one capsule after the meal."]],
 self:[["Bewegt sich das Papier bei Puls – und bei Bein nicht?","Does the paper move on Puls – and not on Bein?"],["Hören Sie bei Patient einen Hauch nach dem p?","Do you hear a puff after the p in Patient?"]],
 meph:["Puls. Mit P. Sie haben soeben einem Patienten das Leben gerettet – vor einem Missverständnis.","Pulse. With a P. You have just saved a patient's life – from a misunderstanding."]},

{id:"lt13",n:13,lv:0,theme:"konsonanten",dia:"",t:"w, v und f",en:"w, v and f",
 rule:["w ist immer [v], nie englisches w. v ist [f] in deutschen Wörtern (Vater, viel, vor, Vogel, Verband) und [v] in lateinischen und französischen Lehnwörtern – den meisten medizinischen (Vene, Virus, Visite, Vitamin, Ventrikel, nervös). f ist immer [f].","German w is always [v], never English w. v is [f] in native words (Vater, viel, vor, Vogel, Verband) and [v] in Latin and French loans – most medical words (Vene, Virus, Visite, Vitamin, Ventrikel, nervös). f is always [f]."],
 trap:{ar:["Arabisch hat ف, aber kein v: Dann klingt alles wie f – wir wird vier. Für deutsches v in Vater ist f richtig, für w und Vene nicht.","Arabic has ف but no v, so everything turns into f – wir becomes vier. For native v in Vater, f is right; for w and Vene it is not."],
       en:["Englisch spricht w als [w] (Wunde wie „woonde“). Im Deutschen berühren die Zähne die Lippe.","English says w as [w] (Wunde like 'woonde'). In German the teeth touch the lip."]},
 art:["Für [v] berühren die oberen Zähne leicht die Unterlippe, und die Stimme summt. Für [f]: gleiche Stellung, aber nur Luft, keine Stimme. Die Lippen werden nie rund wie beim englischen w.","For [v] the upper teeth touch the lower lip lightly and the voice buzzes. For [f]: the same position but only air, no voice. The lips never round as for English w."],
 pairs:[["Wein","fein","vaɪ̯n","faɪ̯n","v-f"],["Wetter","Vetter","ˈvɛtɐ","ˈfɛtɐ","v-f"],["wir","vier","viːɐ̯","fiːɐ̯","v-f"],["Wald","bald","valt","balt","v-b"],["Wunde","Funde","ˈvʊndə","ˈfʊndə","v-f"],["Wall","Fall","val","fal","v-f"],["Welle","Felle","ˈvɛlə","ˈfɛlə","v-f"],["Wade","fade","ˈvaːdə","ˈfaːdə","v-f"],["Vater","Vase","ˈfaːtɐ","ˈvaːzə","v=f/v=v"],["viel","Ventil","fiːl","vɛnˈtiːl","v=f/v=v"],["Verband","Vene","fɛɐ̯ˈbant","ˈveːnə","v=f/v=v"],["Wort","fort","vɔʁt","fɔʁt","v-f"]],
 words:["wir","Wunde","Wade","Verband","Vene","Virus","Visite","nervös"],
 sent:[["Wir wechseln den Verband der Wunde.","We are changing the dressing on the wound."],["Wo tut es weh – vorne oder in der Wade?","Where does it hurt – at the front or in the calf?"],["Nach der Visite nehmen wir Blut aus der Vene ab.","After the ward round we take blood from the vein."]],
 self:[["Berühren Ihre oberen Zähne bei Wunde die Unterlippe?","Do your upper teeth touch the lower lip for Wunde?"],["Sagen Sie Vene mit summendem [v] und Vater mit [f]?","Do you say Vene with a buzzing [v] and Vater with [f]?"]],
 meph:["Vene mit v, Vater mit f. Die Sprache ist unlogisch – wie Ihre Patienten. Sie sind trotzdem durchgekommen.","Vene with v, Vater with f. The language is illogical – like your patients. You got through anyway."]},

{id:"lt14",n:14,lv:0,theme:"konsonanten",dia:"z",t:"z [ts], s [z] und ß [s]",en:"z [ts], voiced s [z], ß/ss [s]",
 rule:["z ist immer t + s [ts] (Zahn, Herz, Arzt). s vor einem Vokal ist stimmhaft [z] (Salbe, Rose, Gesicht). ß und ss sind immer stimmlos [s] (Fuß, Wasser).","z is always t + s [ts] (Zahn, Herz, Arzt). s before a vowel is voiced [z] (Salbe, Rose, Gesicht). ß and ss are always voiceless [s] (Fuß, Wasser)."],
 trap:{ar:["ز für s vor Vokal ist richtig. Aber [ts] ist eine neue Verbindung – nicht s und nicht „ds“ sagen.","ز for s before a vowel is right. But [ts] is a new combination – do not say s or 'ds'."],
       en:["Englisch liest z als [z] (zoo) und s am Anfang als [s]. Im Deutschen ist es umgekehrt.","English reads z as [z] (zoo) and initial s as [s]. German does it the other way round."]},
 art:["Für z setzen Sie die Zungenspitze kurz an den Zahndamm (t) und lassen sofort in ein scharfes s los – ein einziger Laut, keine Pause. Stimmhaftes s summt wie eine Biene; ß zischt wie eine Schlange, ohne Summen.","For z put the tongue tip briefly on the gum ridge (t) and release at once into a sharp s – one single sound, no pause. Voiced s buzzes like a bee; ß hisses like a snake, without a buzz."],
 pairs:[["Zahl","Saal","tsaːl","zaːl","ts-z"],["Zeit","seit","tsaɪ̯t","zaɪ̯t","ts-z"],["Zehen","sehen","ˈtseːən","ˈzeːən","ts-z"],["Zoll","soll","tsɔl","zɔl","ts-z"],["Zoo","so","tsoː","zoː","ts-z"],["reisen","reißen","ˈʁaɪ̯zn̩","ˈʁaɪ̯sn̩","z-s"],["Muse","Muße","ˈmuːzə","ˈmuːsə","z-s"],["weise","weiße","ˈvaɪ̯zə","ˈvaɪ̯sə","z-s"],["Kasse","Katze","ˈkasə","ˈkatsə","s-ts"],["heißen","heizen","ˈhaɪ̯sn̩","ˈhaɪ̯tsn̩","s-ts"],["Sinn","Zinn","zɪn","tsɪn","ts-z"]],
 words:["Herz","Schmerz","Arzt","Spritze","Blutzucker","Zunge","sitzen","Salbe"],
 sent:[["Seit zehn Tagen zieht der Schmerz zum Herzen.","For ten days the pain has been radiating to the heart."],["Der Blutzucker ist zu hoch.","The blood sugar is too high."],["Setzen Sie sich bitte; der Pieks dauert nur kurz.","Please sit down; the prick only takes a moment."]],
 self:[["Ist Ihr z in Zeit ein kurzer Laut ohne Pause zwischen t und s?","Is your z in Zeit one short sound with no gap between t and s?"],["Summt Ihr s in sehen?","Does your s in sehen buzz?"]],
 meph:["Zehen, nicht sehen. Sie wissen jetzt, wo Sie hinschauen müssen.","Toes, not see. Now you know where to look."]},

{id:"lt15",n:15,lv:0,theme:"konsonanten",dia:"",t:"sp und st am Wortanfang",en:"sp-, st- = [ʃp ʃt]",
 rule:["Am Anfang eines Wortes oder Wortstamms spricht man sp und st als [ʃp] und [ʃt]: Spritze, Stuhl, ver-stehen, auf-stehen. Sonst [sp], [st]: Husten, Wespe, ist, fast, Hospital.","At the start of a word or stem, sp and st are [ʃp] and [ʃt]: Spritze, Stuhl, ver-stehen, auf-stehen. Elsewhere [sp], [st]: Husten, Wespe, ist, fast, Hospital."],
 trap:{ar:["Arabisch setzt vor zwei Konsonanten gern einen Vokal: „Eschtuhl“. Beginnen Sie direkt mit sch.","Arabic likes to put a vowel before two consonants: 'Eschtuhl'. Start directly with sch."],
       en:["Englisch sagt s-t (Stuhl wie „stool“). Am Wortanfang ist es im Deutschen sch-t.","English says s-t (Stuhl like 'stool'). At the start of a German word it is sh-t."]},
 art:["Runden Sie die Lippen leicht und sagen Sie sch; ohne Pause folgt t oder p. Kein Vokal davor: nicht „e-schtehen“, sondern „schtehen“.","Round the lips slightly and say sh; t or p follows without a pause. No vowel in front: not 'e-shtehen' but 'shtehen'."],
 pairs:[["Stier","Tier","ʃtiːɐ̯","tiːɐ̯","ʃt-t"],["Stau","Tau","ʃtaʊ̯","taʊ̯","ʃt-t"],["Staub","taub","ʃtaʊ̯p","taʊ̯p","ʃt-t"],["Spur","pur","ʃpuːɐ̯","puːɐ̯","ʃp-p"],["Sport","Port","ʃpɔʁt","pɔʁt","ʃp-p"],["Stein","Schein","ʃtaɪ̯n","ʃaɪ̯n","ʃt-ʃ"],["Spaten","Paten","ˈʃpaːtn̩","ˈpaːtn̩","ʃp-p"],["Spanne","Panne","ˈʃpanə","ˈpanə","ʃp-p"],["Steuer","teuer","ˈʃtɔʏ̯ɐ","ˈtɔʏ̯ɐ","ʃt-t"],["sparen","paaren","ˈʃpaːʁən","ˈpaːʁən","ʃp-p"],["Stunde","Kunde","ˈʃtʊndə","ˈkʊndə","ʃt-k"]],
 words:["Sprechstunde","Spritze","Stuhl","Station","verstehen","aufstehen","Husten","Hospital"],
 sent:[["Stehen Sie bitte auf und sprechen Sie mit der Stationsschwester.","Please stand up and speak to the ward sister."],["Der Husten ist fast weg, ein Stich bleibt.","The cough is almost gone; a stabbing pain remains."],["Zwei Stunden nach der Spritze spürte sie nichts mehr.","Two hours after the injection she no longer felt anything."]],
 self:[["Beginnt Ihr Stuhl mit sch – ohne Vokal davor?","Does your Stuhl start with sh – without a vowel in front?"],["Sagen Sie Husten mit [st], nicht [ʃt]?","Do you say Husten with [st], not [ʃt]?"]],
 meph:["Schtuhl. Nicht „stool“ wie ein englischer Hocker. Setzen Sie sich – ausnahmsweise haben Sie es verdient.","Shtuhl. Not 'stool' like an English footstool. Sit down – for once you have earned it."]},

{id:"lt16",n:16,lv:1,theme:"konsonanten",dia:"",t:"Konsonantengruppen: pf, kn, ps, -rzt",en:"Consonant clusters without helper vowels",
 rule:["Deutsch erlaubt dichte Konsonantengruppen: pf, kn, ps, ts, -rzt, -mpf, -bst, -chts. Alle Konsonanten werden gesprochen, ohne Hilfsvokal davor oder dazwischen. Das k in Knie ist hörbar.","German allows dense clusters: pf, kn, ps, ts, -rzt, -mpf, -bst, -chts. Every consonant is spoken, with no helper vowel before or between them. The k in Knie is audible."],
 trap:{ar:["Arabische Silben beginnen nicht mit zwei Konsonanten; daher entstehen Hilfsvokale: „esprechen“, „Kinie“, „Arzit“.","Arabic syllables do not start with two consonants, so helper vowels appear: 'esprechen', 'Kinie', 'Arzit'."],
       en:["Englisch lässt das k in knee und das p in psychology fallen. Im Deutschen nicht: Knie, Psychiatrie.","English drops the k in knee and the p in psychology. German does not: Knie, Psychiatrie."]},
 art:["Bauen Sie von hinten auf: -zt → rzt → Arzt; -mpf → Strumpf. Bei pf schließen die Lippen für p und öffnen direkt in f – die Unterlippe bleibt an den Zähnen. Bei kn liegen k (hinten) und n (vorn) fast gleichzeitig.","Build from the back: -zt → rzt → Arzt; -mpf → Strumpf. For pf the lips close for p and open straight into f – the lower lip stays on the teeth. For kn, k (back) and n (front) come almost at the same time."],
 pairs:[["Pfund","Fund","pfʊnt","fʊnt","pf-f"],["Pfeil","feil","pfaɪ̯l","faɪ̯l","pf-f"],["Pfahl","fahl","pfaːl","faːl","pf-f"],["Pflug","Flug","pfluːk","fluːk","pf-f"],["Knie","nie","kniː","niː","kn-n"],["Knoten","Noten","ˈknoːtn̩","ˈnoːtn̩","kn-n"],["knicken","nicken","ˈknɪkn̩","ˈnɪkn̩","kn-n"],["Kapsel","Kassel","ˈkapsl̩","ˈkasl̩","ps-s"],["Arzt","Art","aːɐ̯tst","aːɐ̯t","rzt-rt"],["Herbst","herb","hɛʁpst","hɛʁp","bst-b"],["nichts","nicht","nɪçts","nɪçt","chts-cht"],["Kampf","Kamm","kampf","kam","mpf-m"]],
 words:["Pflege","Pflaster","Impfung","Knie","Knöchel","Psychiatrie","Zwerchfell","Schnupfen"],
 sent:[["Gegen Schnupfen gibt es keine Impfung.","There is no vaccine against a cold."],["Der Knöchel und das Knie sind geprellt.","The ankle and the knee are bruised."],["Der Arzt kommt jetzt – haben Sie keine Angst.","The doctor is coming now – do not be afraid."]],
 self:[["Hört man in Knie ein k vor dem n?","Can you hear a k before the n in Knie?"],["Sagen Sie Arzt in einer Silbe, ohne „Arzit“?","Do you say Arzt in one syllable, without 'Arzit'?"]],
 meph:["Knie mit K. Sie haben einen Buchstaben gerettet, den die Engländer längst begraben haben.","Knie with a K. You have rescued a letter the English buried long ago."]},

{id:"lt17",n:17,lv:0,theme:"konsonanten",dia:"ng",t:"ng [ŋ] und nk [ŋk]",en:"ng [ŋ] and nk [ŋk]",
 rule:["ng ist ein einziger Nasallaut [ŋ], hinten im Mund, ohne g danach: Lunge = „Lu-nge“ ohne g, Finger wie englisch singer. Bei nk folgt ein hörbares k: krank, links, trinken.","ng is one single nasal [ŋ] at the back of the mouth, with no g after it: Lunge without a g, Finger like English singer. In nk an audible k follows: krank, links, trinken."],
 trap:{ar:["Arabisch hängt gern ein g an: „Lun-ge“, „Fin-ger“. Das g bleibt stumm.","Arabic speakers tend to add a g: 'Lun-ge', 'Fin-ger'. The g stays silent."],
       en:["In singer richtig, in finger falsch: Englisch spricht dort ein g. Deutsch Finger klingt wie singer.","Right in singer, wrong in finger: English pronounces a g there. German Finger sounds like singer."]},
 art:["Der hintere Zungenrücken schließt am weichen Gaumen, die Luft geht durch die Nase – wie am Ende von englisch sing. Lösen Sie den Verschluss weich in den nächsten Vokal, ohne Knall.","The back of the tongue closes against the soft palate and the air goes through the nose – as at the end of English sing. Release the closure softly into the next vowel, without a pop."],
 pairs:[["sinken","singen","ˈzɪŋkn̩","ˈzɪŋən","ŋk-ŋ"],["Dank","dann","daŋk","dan","ŋk-n"],["Gang","Gans","ɡaŋ","ɡans","ŋ-n"],["sang","sank","zaŋ","zaŋk","ŋ-ŋk"],["Wangen","wanken","ˈvaŋən","ˈvaŋkn̩","ŋ-ŋk"],["lang","Land","laŋ","lant","ŋ-n"],["singen","sinnen","ˈzɪŋən","ˈzɪnən","ŋ-n"],["Ringe","Rinne","ˈʁɪŋə","ˈʁɪnə","ŋ-n"],["Engel","Enkel","ˈɛŋl̩","ˈɛŋkl̩","ŋ-ŋk"],["Schlange","schlanke","ˈʃlaŋə","ˈʃlaŋkə","ŋ-ŋk"]],
 words:["Lunge","Zunge","Finger","Hunger","Behandlung","Untersuchung","krank","links"],
 sent:[["Die Lunge ist entzündet, die Zunge belegt.","The lung is inflamed, the tongue coated."],["Die Untersuchung dauert nicht lange.","The examination will not take long."],["Trinken Sie langsam.","Drink slowly."]],
 self:[["Hört man nach dem ng in Lunge kein g?","Is there no g after the ng in Lunge?"],["Hört man in krank ein k am Ende?","Is there a k at the end of krank?"]],
 meph:["Lunge ohne g. Endlich atmet das Wort.","Lunge without a g. At last the word breathes."]},

{id:"lt18",n:18,lv:1,theme:"konsonanten",dia:"glottis",t:"Fester Einsatz [ʔ] – keine Bindung",en:"Glottal stop – no linking",
 rule:["Deutsch beginnt jedes Wort und jeden Wortstamm, der mit einem Vokal anfängt, mit einem kurzen Verschluss der Stimmlippen [ʔ] – dem festen Einsatz. Wörter werden nicht aneinandergebunden: in | einer | Stunde, nicht „i-nei-ner“. Auch in Zusammensetzungen: Not|aufnahme, Blut|untersuchung.","German starts every word and stem that begins with a vowel with a brief closure of the vocal folds [ʔ] – the glottal stop. Words are not linked: in | einer | Stunde, not 'i-nei-ner'. Also inside compounds: Not|aufnahme, Blut|untersuchung."],
 trap:{ar:["Das ist die Hamza ء – Sie können es schon! Aber Arabisch bindet Wörter (Wasla); Deutsch bindet nie.","This is the hamza ء – you can already do it! But Arabic links words (wasla); German never links."],
       en:["Englisch bindet (an_apple, in_an_hour). Im Deutschen beginnt jedes Vokalwort neu.","English links words (an_apple, in_an_hour). In German every vowel-initial word starts afresh."]},
 art:["Sagen Sie „Oh-oh!“ wie bei einem kleinen Missgeschick: Der winzige Stopp in der Kehle vor dem zweiten o ist der feste Einsatz. Er ist kurz und leise – kein Husten, kein Druck.","Say 'uh-oh!' as after a small mishap: the tiny stop in the throat before the second vowel is the glottal stop. It is short and quiet – no cough, no pressure."],
 hint:["Ich | ordne | eine | Urin|untersuchung | an.","In | einer | Stunde | ist | er | im | OP."],
 pairs:[["vereisen","verreisen","fɛɐ̯ˈʔaɪ̯zn̩","fɛɐ̯ˈʁaɪ̯zn̩","ʔ-r"],["beinhalten","Bein halten","bəˈʔɪnhaltn̩","baɪ̯n ˈhaltn̩","ʔ-Bindung"],["Urinstinkt","Urin stinkt","ˈuːɐ̯ʔɪnstɪŋkt","uˈʁiːn ʃtɪŋkt","ʔ-Bindung"],["Stau|becken","Staub|ecken","ˈʃtaʊ̯bɛkn̩","ˈʃtaʊ̯pʔɛkn̩","ʔ-Bindung","","Stau-Becken","Staub-Ecken"],["Wach|stube","Wachs|tube","ˈvaxʃtuːbə","ˈvakstuːbə","Fuge","","Wach-Stube","Wachs-Tube"],["Druck|erzeugnis","Drucker|zeugnis","ˈdʁʊkʔɛɐ̯tsɔʏ̯knɪs","ˈdʁʊkɐtsɔʏ̯knɪs","ʔ-Bindung","","Druck-Erzeugnis","Drucker-Zeugnis"],["Spiel|ende","spielende","ˈʃpiːlʔɛndə","ˈʃpiːləndə","ʔ-Bindung","","Spiel-Ende","spielende"],["Musik|erleben","Musiker|leben","muˈziːkʔɛɐ̯leːbn̩","ˈmuːzikɐleːbn̩","ʔ-Bindung","","Musik erleben","Musiker leben"],["Erb|information","Erbin|formation","ˈɛʁpʔɪnfɔʁmaˌtsi̯oːn","ˈɛʁbɪnfɔʁmaˌtsi̯oːn","ʔ-Bindung","","Erb-Information","Erbin-Formation"],["Altbau|erhaltung","Altbauer|haltung","ˈaltbaʊ̯ʔɛɐ̯haltʊŋ","ˈaltbaʊ̯ɐhaltʊŋ","ʔ-Bindung","","Altbau-Erhaltung","Altbauer-Haltung"],["Blut|erguss","Bluter|guss","ˈbluːtʔɛɐ̯ɡʊs","ˈbluːtɐɡʊs","ʔ-Bindung","","Bluterguss","Bluter-Guss"]],
 words:["Notaufnahme","Blutuntersuchung","beobachten","geöffnet","geimpft","Theater","überall","anordnen"],
 sent:[["Ich ordne eine Urinuntersuchung an.","I am ordering a urine test."],["In einer Stunde ist er im OP.","In an hour he will be in theatre."],["Atmen Sie ein – und wieder aus.","Breathe in – and out again."]],
 self:[["Spüren Sie vor einer einen kleinen Stopp in der Kehle?","Do you feel a small stop in your throat before einer?"],["Bleiben in und einer bei Ihnen getrennt?","Do in and einer stay separate when you say them?"]],
 meph:["Ur|instinkt. Urin | stinkt. Sie hören den Unterschied – und ich höre zum ersten Mal einen Arzt, der ihn auch spricht.","Primal instinct. Urine stinks. You hear the difference – and for the first time I hear a doctor who also says it."]},

{id:"lt19",n:19,lv:0,theme:"konsonanten",dia:"",t:"Das h",en:"h",
 rule:["h spricht man nur am Anfang eines Wortes oder Wortstamms: ein leiser Hauch [h] (Hals, Husten, be-handeln). Nach einem Vokal ist h stumm und macht den Vokal lang (gehen, Zahn, Ruhe).","h is spoken only at the start of a word or stem: a soft breath [h] (Hals, Husten, be-handeln). After a vowel h is silent and makes the vowel long (gehen, Zahn, Ruhe)."],
 trap:{ar:["Das deutsche h ist das weiche ه – nie ح (gepresst) und nie خ (kratzend). Lassen Sie es aber auch nicht weg: Hals wird sonst als.","German h is the soft ه – never ح (pressed) and never خ (scraping). But do not drop it either, or Hals becomes als."],
       en:["Englisch ist hier richtig. Nur das stumme h in gehen nicht sprechen.","English is right here. Just do not pronounce the silent h in gehen."]},
 art:["Hauchen Sie warme Luft auf eine kalte Brille: Das ist h. Kein Druck in der Kehle, keine Reibung im Mund.","Breathe warm air onto a cold pair of glasses: that is h. No pressure in the throat, no friction in the mouth."],
 pairs:[["Haus","aus","haʊ̯s","ʔaʊ̯s","h-ʔ"],["Hals","als","hals","ʔals","h-ʔ"],["hier","ihr","hiːɐ̯","ʔiːɐ̯","h-ʔ"],["heiß","Eis","haɪ̯s","ʔaɪ̯s","h-ʔ"],["Hund","und","hʊnt","ʔʊnt","h-ʔ"],["hoffen","offen","ˈhɔfn̩","ˈʔɔfn̩","h-ʔ"],["Halle","alle","ˈhalə","ˈʔalə","h-ʔ"],["Hecke","Ecke","ˈhɛkə","ˈʔɛkə","h-ʔ"],["Herz","Erz","hɛʁts","ʔeːɐ̯ts","h-ʔ"],["Hast","Ast","hast","ʔast","h-ʔ"],["heilen","eilen","ˈhaɪ̯lən","ˈʔaɪ̯lən","h-ʔ"]],
 words:["Husten","Halsschmerzen","Herz","Hilfe","gehen","sehen","Zahn","Ruhe"],
 sent:[["Haben Sie Husten oder Halsschmerzen?","Do you have a cough or a sore throat?"],["Der Zahn und das Ohr tun weh.","The tooth and the ear hurt."],["Gehen Sie in Ruhe nach Hause.","Go home and take it easy."]],
 self:[["Ist Ihr h in Hals nur ein Hauch – ohne Druck?","Is your h in Hals just a breath – without pressure?"],["Bleibt das h in gehen stumm?","Does the h in gehen stay silent?"]],
 meph:["Hals, nicht als. Ihr Patient hatte Halsschmerzen, keine Konjunktion.","Throat, not 'as'. Your patient had a sore throat, not a conjunction."]},

{id:"lt20",n:20,lv:1,theme:"vokale",dia:"",t:"Schwa [ə] und die Endungen -e, -en, -em",en:"Schwa and reduced endings",
 rule:["Ein unbetontes e am Ende ist ein kurzer, neutraler Laut [ə] – nie weggelassen, nie ein volles e. In -en verschwindet das e meist, und das n passt sich an: haben ≈ „habm“, legen ≈ „legŋ“, bitten ≈ „bittn“. Die Endung trägt Grammatik: einen ≠ einem.","An unstressed final e is a short, neutral sound [ə] – never dropped, never a full e. In -en the e usually disappears and the n adapts: haben ≈ 'habm', legen ≈ 'legng', bitten ≈ 'bittn'. The ending carries grammar: einen ≠ einem."],
 trap:{ar:["Entweder fällt das -e weg („bitt“) oder es wird ein volles e/i („bitti“). Beides verändert die Grammatik, die man hört.","Either the -e is dropped ('bitt') or it becomes a full e/i ('bitti'). Both change the grammar the listener hears."],
       en:["Im Englischen ist ein -e am Ende oft stumm (like, make). Im Deutschen wird es gesprochen: Lun-ge, Tablet-te.","In English a final -e is often silent (like, make). In German it is spoken: Lun-ge, Tablet-te."]},
 art:["Für Schwa ist der Mund halb offen, die Zunge völlig entspannt in der Mitte, die Lippen neutral – der kürzeste, faulste Vokal, den Sie haben. Bei -en folgt das n direkt auf den Konsonanten, ohne Vokal dazwischen.","For schwa the mouth is half open, the tongue completely relaxed in the middle, the lips neutral – the shortest, laziest vowel you have. In -en the n follows the consonant directly, with no vowel between."],
 extra:["Nur zum Verstehen, nicht für die Prüfung: In schneller Umgangssprache hören Sie ham (haben), hamse (haben Sie), wolln (wollen), ein'n (einen), 'n bisschen, isses (ist es).","For understanding only, not for the exam: in fast colloquial speech you will hear ham (haben), hamse (haben Sie), wolln (wollen), ein'n (einen), 'n bisschen, isses (ist es)."],
 pairs:[["eine","einen","ˈaɪ̯nə","ˈaɪ̯nən","ə-ən"],["einen","einem","ˈaɪ̯nən","ˈaɪ̯nəm","n-m"],["guten","gutem","ˈɡuːtn̩","ˈɡuːtəm","n-m"],["Katze","Katzen","ˈkatsə","ˈkatsn̩","ə-ən"],["kleine","kleinen","ˈklaɪ̯nə","ˈklaɪ̯nən","ə-ən"],["den","dem","deːn","deːm","n-m"],["Hose","Hosen","ˈhoːzə","ˈhoːzn̩","ə-ən"],["Bitte","bitten","ˈbɪtə","ˈbɪtn̩","ə-ən"],["Tablette","Tabletten","taˈblɛtə","taˈblɛtn̩","ə-ən"],["Lunge","Lungen","ˈlʊŋə","ˈlʊŋən","ə-ən"],["Probe","Proben","ˈpʁoːbə","ˈpʁoːbm̩","ə-ən"]],
 words:["bitte","Lunge","Leber","Löffel","Mantel","Atem","haben","legen"],
 sent:[["Haben Sie heute Morgen schon etwas gegessen?","Have you eaten anything yet this morning?"],["Legen Sie bitte den Mantel ab.","Please take off your coat."],["Wir geben Ihnen einen neuen Termin.","We will give you a new appointment."]],
 self:[["Ist Ihr -e in bitte kurz und neutral – weder weg noch „i“?","Is your -e in bitte short and neutral – neither gone nor 'ee'?"],["Hört man bei einem am Ende ein m?","Can you hear an m at the end of einem?"]],
 meph:["Einen, einem – die Endung war hörbar. Grammatik, die man hört. Ich gebe zu: Ich bin überrascht.","Einen, einem – the ending was audible. Grammar you can hear. I admit it: I am surprised."]},

{id:"lt21",n:21,lv:1,theme:"betonung",dia:"",t:"Wortakzent: trennbare und untrennbare Verben",en:"Word stress in verbs",
 rule:["Trennbare Vorsilben sind betont: {an}rufen, {auf}nehmen, {ab}hören, {zu}nehmen, {ein}weisen. be-, ge-, er-, ver-, zer-, ent-, emp-, miss- sind nie betont: be{su}chen, ver{schrei}ben, ent{las}sen, unter{su}chen. Bei um-, über-, unter-, durch-, wieder- entscheidet der Akzent die Bedeutung: {um}fahren (umstoßen) – um{fah}ren (um etwas herumfahren); wieder{ho}len (noch einmal sagen) – {wie}derholen (zurückholen).","Separable prefixes are stressed: {an}rufen, {auf}nehmen, {ab}hören, {zu}nehmen, {ein}weisen. be-, ge-, er-, ver-, zer-, ent-, emp-, miss- are never stressed: be{su}chen, ver{schrei}ben, ent{las}sen, unter{su}chen. With um-, über-, unter-, durch-, wieder- the stress decides the meaning: {um}fahren (knock down) – um{fah}ren (drive round); wieder{ho}len (repeat) – {wie}derholen (fetch back)."],
 trap:{ar:["Arabisch betont oft die schwere Silbe nahe am Wortende. Deutsche Verben betonen den Stamm oder die trennbare Vorsilbe.","Arabic often stresses the heavy syllable near the end. German verbs stress the stem or the separable prefix."],
       en:["Englische Muster passen nicht: under{stand}, aber {un}terstellen und unter{stel}len sind zwei Verben.","English patterns do not transfer: under{stand}, but {un}terstellen and unter{stel}len are two different verbs."]},
 art:["Betonung heißt im Deutschen: lauter, länger und etwas höher. Die unbetonten Silben werden kurz und leise (be-, ge-, -en). Klopfen Sie die betonte Silbe auf den Tisch.","In German, stress means louder, longer and a little higher. Unstressed syllables become short and quiet (be-, ge-, -en). Tap the stressed syllable on the table."],
 pairs:[["{um}gefahren","um{fah}ren","ˈʊmɡəfaːʁən","ʊmˈfaːʁən","trennbar-untrennbar"],["{ü}bergesetzt","über{setzt}","ˈyːbɐɡəzɛtst","yːbɐˈzɛtst","trennbar-untrennbar"],["{un}tergestellt","unter{stellt}","ˈʊntɐɡəʃtɛlt","ʊntɐˈʃtɛlt","trennbar-untrennbar"],["{wie}dergeholt","wieder{holt}","ˈviːdɐɡəhoːlt","viːdɐˈhoːlt","trennbar-untrennbar"],["{durch}geschaut","durch{schaut}","ˈdʊʁçɡəʃaʊ̯t","dʊʁçˈʃaʊ̯t","trennbar-untrennbar"],["{um}gegangen","um{gan}gen","ˈʊmɡəɡaŋən","ʊmˈɡaŋən","trennbar-untrennbar"],["{durch}gebrochen","durch{bro}chen","ˈdʊʁçɡəbʁɔxn̩","dʊʁçˈbʁɔxn̩","trennbar-untrennbar"],["{um}geschrieben","um{schrie}ben","ˈʊmɡəʃʁiːbn̩","ʊmˈʃʁiːbn̩","trennbar-untrennbar"],["{ü}bergegangen","über{gan}gen","ˈyːbɐɡəɡaŋən","yːbɐˈɡaŋən","trennbar-untrennbar"],["{um}gestellt","um{stellt}","ˈʊmɡəʃtɛlt","ʊmˈʃtɛlt","trennbar-untrennbar"],["{durch}gelaufen","durch{lau}fen","ˈdʊʁçɡəlaʊ̯fn̩","dʊʁçˈlaʊ̯fn̩","trennbar-untrennbar"],["{ü}bergelaufen","über{lau}fen","ˈyːbɐɡəlaʊ̯fn̩","yːbɐˈlaʊ̯fn̩","trennbar-untrennbar"]],
 words:["{an}rufen","{auf}nehmen","{ab}hören","be{su}chen","ver{schrei}ben","ent{las}sen","unter{su}chen","über{wei}sen"],
 sent:[["Ich unter{su}che Sie, dann weise ich Sie {ein}.","I will examine you, then I will admit you."],["Bitte wieder{ho}len Sie das.","Please repeat that."],["Wir über{wei}sen Sie und rufen morgen {an}.","We will refer you and call tomorrow."]],
 stress:[["Bitte wiederholen Sie das.","wie·der·ho·len",2,"Please repeat that."],["Ich muss Sie leider überweisen.","über·wei·sen",1,"Unfortunately I have to refer you."],["Wir müssen Sie stationär aufnehmen.","auf·neh·men",0,"We need to admit you to the ward."],["Darf ich Ihre Lunge abhören?","ab·hö·ren",0,"May I listen to your lungs?"],["Ich möchte Sie kurz untersuchen.","un·ter·su·chen",2,"I would like to examine you briefly."],["Wann wurden Sie entlassen?","ent·las·sen",1,"When were you discharged?"],["Ich verschreibe Ihnen ein Schmerzmittel.","ver·schrei·be",1,"I am prescribing you a painkiller."],["Haben Sie schon erbrochen?","er·bro·chen",1,"Have you vomited yet?"],["Sie können mich jederzeit anrufen.","an·ru·fen",0,"You can call me at any time."],["Der Fußgänger wurde umgefahren.","um·ge·fah·ren",0,"The pedestrian was knocked down."],["Der Radfahrer hat das Hindernis umfahren.","um·fah·ren",1,"The cyclist rode around the obstacle."],["Haben Sie in letzter Zeit zugenommen?","zu·ge·nom·men",0,"Have you gained weight recently?"],["Der Hausarzt hat ihn eingewiesen.","ein·ge·wie·sen",0,"The GP referred him for admission."],["Wir haben ihm den Befund mitgeteilt.","mit·ge·teilt",0,"We told him the result."],["Können Sie das bitte übersetzen?","ü·ber·set·zen",2,"Can you translate that, please?"],["Darf ich mich kurz vorstellen?","vor·stel·len",0,"May I briefly introduce myself?"],["Die Wunde ist gut verheilt.","ver·heilt",1,"The wound has healed well."],["Wir besprechen das Ergebnis morgen.","be·spre·chen",1,"We will discuss the result tomorrow."],["Bitte unterschreiben Sie hier.","un·ter·schrei·ben",2,"Please sign here."],["Der Patient hat die Tabletten abgesetzt.","ab·ge·setzt",0,"The patient stopped taking the tablets."]],
 self:[["Ist bei Ihnen in wiederholen die Silbe ho am lautesten?","In wiederholen, is ho your loudest syllable?"],["Sind be- und ver- bei Ihnen kurz und leise?","Are be- and ver- short and quiet when you say them?"]],
 meph:["Um{fah}ren, nicht {um}gefahren. Der Patient lebt. Sie lernen, mit Silben Leben zu retten.","Drove round, not knocked down. The patient lives. You are learning to save lives with syllables."]},

{id:"lt22",n:22,lv:1,theme:"betonung",dia:"",t:"Akzent in Zusammensetzungen und Abkürzungen",en:"Stress in compounds and abbreviations",
 rule:["In Zusammensetzungen trägt das erste Glied den Hauptakzent: {Blut}druck, {Not}aufnahme, {Kran}kenhaus, {Herz}infarkt, {Arzt}brief. Ausnahmen zum Merken: Jahr{hun}dert, Jahr{zehnt}. Ortsnamen folgen der Regel: {Hei}delberg, {Mann}heim. Buchstaben-Abkürzungen betonen den letzten Buchstaben: E-K-{G}, C-{T}, M-R-{T}, Z-N-{A}, O-{P}, C-R-{P}. Ein hohes {Haus} ist kein {Hoch}haus: Wortgruppen betonen das Nomen.","In compounds the first element carries the main stress: {Blut}druck, {Not}aufnahme, {Kran}kenhaus, {Herz}infarkt, {Arzt}brief. Exceptions to remember: Jahr{hun}dert, Jahr{zehnt}. Place names follow the rule: {Hei}delberg, {Mann}heim. Letter abbreviations stress the last letter: E-K-{G}, C-{T}, M-R-{T}, Z-N-{A}, O-{P}, C-R-{P}. A tall house (hohes {Haus}) is not a tower block ({Hoch}haus): phrases stress the noun."],
 trap:{ar:["Betonen Sie nicht beide Teile gleich stark. Nur das erste Glied ist laut; der Rest wird leiser.","Do not stress both parts equally. Only the first element is loud; the rest gets quieter."],
       en:["Englisch betont Abkürzungen ähnlich (an E-C-{G}) – gut. Aber Ortsnamen: nicht Heidel{berg}.","English stresses abbreviations similarly (an E-C-{G}) – good. But place names: not Heidel{berg}."]},
 art:["Sprechen Sie das erste Glied laut und lang, den Rest wie ein Echo. Bei Abkürzungen gleiten Sie über die ersten Buchstaben und landen kräftig auf dem letzten.","Say the first element loud and long, the rest like an echo. In abbreviations glide over the first letters and land firmly on the last one."],
 pairs:[["{Hoch}haus","hohes {Haus}","","","Kompositum-Wortgruppe"],["{Groß}vater","großer {Va}ter","","","Kompositum-Wortgruppe"],["{Rot}wein","roter {Wein}","","","Kompositum-Wortgruppe"],["{Schwarz}brot","schwarzes {Brot}","","","Kompositum-Wortgruppe"],["{Klein}kind","kleines {Kind}","","","Kompositum-Wortgruppe"],["{Neu}bau","neuer {Bau}","","","Kompositum-Wortgruppe"],["{Blau}licht","blaues {Licht}","","","Kompositum-Wortgruppe"],["{Hoch}druck","hoher {Druck}","","","Kompositum-Wortgruppe"],["{Früh}geburt","frühe Ge{burt}","","","Kompositum-Wortgruppe"],["{Fremd}körper","fremder {Kör}per","","","Kompositum-Wortgruppe"],["{Dick}darm","dicker {Darm}","","","Kompositum-Wortgruppe"],["{Schwer}punkt","schwerer {Punkt}","","","Kompositum-Wortgruppe"]],
 words:["{Blut}druck","{Not}aufnahme","{Kran}kenhaus","{Herz}infarkt","{Schmerz}mittel","{Arzt}brief","E-K-{G}","C-{T}"],
 sent:[["Im E-K-{G} sehen wir einen {Herz}infarkt.","On the ECG we see a heart attack."],["Der {Blut}druck in der {Not}aufnahme war hoch.","The blood pressure in the emergency department was high."],["Nach dem C-{T} geht sie in den O-{P}.","After the CT she goes to theatre."]],
 stress:[["Der Blutdruck ist zu hoch.","Blut·druck",0,"The blood pressure is too high."],["Sie liegt in der Notaufnahme.","Not·auf·nah·me",0,"She is in the emergency department."],["Wir machen sofort ein EKG.","E·K·G",2,"We will do an ECG straight away."],["Er hatte einen Herzinfarkt.","Herz·in·farkt",0,"He had a heart attack."],["Brauchen Sie ein Schmerzmittel?","Schmerz·mit·tel",0,"Do you need a painkiller?"],["Der Arztbrief ist fertig.","Arzt·brief",0,"The discharge letter is ready."],["Das CT zeigt keine Blutung.","C·T",1,"The CT shows no bleeding."],["Sie kommt auf die Intensivstation.","In·ten·siv·sta·tion",2,"She is going to intensive care."],["Wir nehmen Blut für ein großes Blutbild ab.","Blut·bild",0,"We are taking blood for a full blood count."],["Die Bauchspeicheldrüse ist entzündet.","Bauch·spei·chel·drü·se",0,"The pancreas is inflamed."],["Bitte gehen Sie zur Röntgenabteilung.","Rönt·gen·ab·tei·lung",0,"Please go to the X-ray department."],["Er wohnt in Heidelberg.","Hei·del·berg",0,"He lives in Heidelberg."],["Wir brauchen ein MRT.","M·R·T",2,"We need an MRI."],["Der Patient ist im OP.","O·P",1,"The patient is in theatre."],["Das Krankenhaus liegt in Mannheim.","Kran·ken·haus",0,"The hospital is in Mannheim."],["Die ZNA ist heute voll.","Z·N·A",2,"The central emergency department is full today."],["Wir kontrollieren das CRP.","C·R·P",2,"We will check the CRP."],["Seit einem Jahrzehnt raucht er nicht mehr.","Jahr·zehnt",1,"He has not smoked for a decade."],["Das war im letzten Jahrhundert.","Jahr·hun·dert",1,"That was in the last century."],["Der Hausarzt hat ihn geschickt.","Haus·arzt",0,"His GP sent him."]],
 self:[["Ist bei Blutdruck das Wort Blut lauter als druck?","In Blutdruck, is Blut louder than druck?"],["Landen Sie bei E-K-G kräftig auf dem G?","Do you land firmly on the G of E-K-G?"]],
 meph:["{Blut}druck. Die erste Silbe trägt – wie bei mir der erste Vertrag.","Blood pressure. The first syllable carries the weight – as with me, the first contract does."]},

{id:"lt23",n:23,lv:2,theme:"betonung",dia:"",t:"Akzent in lateinischen und griechischen Fachwörtern",en:"Stress in Latin and Greek medical terms",
 rule:["Die Endung entscheidet. Betontes -{ie}: Thera{pie}, Anä{mie}, Aller{gie}, Embo{lie}. -{i}tis: Appendi{zi}tis, Bron{chi}tis, Gas{tri}tis. -{o}se: Throm{bo}se, Diag{no}se. -{om}: Karzi{nom}, Häma{tom}. -{ion}: Opera{tion}, Infek{tion}. -{ent}: Pati{ent}. -{ur}: Frak{tur}. Unbetontes -ie [i̯ə] mit zwei Lauten: Ar{te}rie, Fa{mi}lie, Bak{te}rie. -or wandert im Plural: {Dok}tor – Dok{to}ren, {Tu}mor – Tu{mo}ren. Laute: ti vor Vokal = [tsi̯] (Pati{ent} = „Pa-tsi-ent“), y = ü (Hyperto{nie}), ph = f, th = t, eu = [ɔʏ] (Pneumo{nie}), Ch vor a, o, l, r = k (chronisch), vor e, i = [ç] (Chi{rurg}).","The suffix decides. Stressed -{ie}: Thera{pie}, Anä{mie}, Aller{gie}, Embo{lie}. -{i}tis: Appendi{zi}tis, Bron{chi}tis, Gas{tri}tis. -{o}se: Throm{bo}se, Diag{no}se. -{om}: Karzi{nom}, Häma{tom}. -{ion}: Opera{tion}, Infek{tion}. -{ent}: Pati{ent}. -{ur}: Frak{tur}. Unstressed -ie [i̯ə], two sounds: Ar{te}rie, Fa{mi}lie, Bak{te}rie. -or moves in the plural: {Dok}tor – Dok{to}ren, {Tu}mor – Tu{mo}ren. Sounds: ti before a vowel = [tsi̯] (Pati{ent} = 'pa-tsi-ENT'), y = ü (Hyperto{nie}), ph = f, th = t, eu = [ɔʏ] (Pneumo{nie}), Ch before a, o, l, r = k (chronisch), before e, i = [ç] (Chi{rurg})."],
 trap:{ar:["Das Muster des Arabischen hilft hier nicht. Lernen Sie die Endungen als Akzentregel – sie gelten für hunderte Wörter.","Arabic patterns do not help here. Learn the suffixes as stress rules – they cover hundreds of words."],
       en:["Die größte Falle: Akzent und Vokale des englischen Wortes. Nicht „die-uh-BEE-teez“, sondern Dia{be}tes; nicht „new-MOH-nia“, sondern Pneumo{nie}; {Ik}terus, {I}leus mit drei Silben, Ka{the}ter, Insu{lin}, Hepa{rin}.","The biggest trap: the stress and vowels of the English cognate. Not 'die-uh-BEE-teez' but Dia{be}tes; not 'new-MOH-nia' but Pneumo{nie}; {Ik}terus, {I}leus in three syllables, Ka{the}ter, Insu{lin}, Hepa{rin}."]},
 art:["Finden Sie zuerst die Endung, dann setzen Sie den Akzent; alle anderen Silben bleiben klar, aber kurz. Bei -ie am Wortende: betont = ein langes i (Thera{pie}); unbetont = i und e getrennt (Fa{mi}li-e).","Find the suffix first, then place the stress; all other syllables stay clear but short. For final -ie: stressed = one long i (Thera{pie}); unstressed = i and e separate (Fa{mi}li-e)."],
 pairs:[["{Dok}tor","Dok{to}ren","ˈdɔktoːɐ̯","dɔkˈtoːʁən","Akzentwechsel"],["{Tu}mor","Tu{mo}ren","ˈtuːmoːɐ̯","tuˈmoːʁən","Akzentwechsel"],["{Fak}tor","Fak{to}ren","ˈfaktoːɐ̯","fakˈtoːʁən","Akzentwechsel"],["Chi{rurg}","Chirur{gie}","çiˈʁʊʁk","çiʁʊʁˈɡiː","Akzentwechsel"],["Thera{pie}","Thera{peut}","teʁaˈpiː","teʁaˈpɔʏ̯t","Endung"],["Al{ler}giker","Aller{gie}","aˈlɛʁɡɪkɐ","alɛʁˈɡiː","Akzentwechsel"],["Diag{no}se","Diag{nos}tik","di̯aˈɡnoːzə","di̯aˈɡnɔstɪk","Endung"],["{Throm}bus","Throm{bo}se","ˈtʁɔmbʊs","tʁɔmˈboːzə","Akzentwechsel"],["Fa{mi}lie","famili{är}","faˈmiːli̯ə","famiˈli̯ɛːɐ̯","-ie unbetont"],["Ar{te}rie","arteri{ell}","aʁˈteːʁi̯ə","aʁteˈʁi̯ɛl","-ie unbetont"],["{Em}bolus","Embo{lie}","ˈɛmbolʊs","ɛmboˈliː","Akzentwechsel"],["Psychi{a}ter","Psychia{trie}","psyˈçi̯aːtɐ","psyçi̯aˈtʁiː","Akzentwechsel"],["Sym{ptom}","sympto{ma}tisch","zʏmpˈtoːm","zʏmptoˈmaːtɪʃ","Endung"],["Anä{mie}","a{nä}misch","anɛˈmiː","aˈnɛːmɪʃ","Akzentwechsel"]],
 words:["Pneumo{nie}","{Sep}sis","Anam{ne}se","Ka{the}ter","{Ik}terus","Insu{lin}","Antibi{o}tikum","Dia{be}tes"],
 sent:[["Verdacht auf Pneumo{nie} mit begleitender {Sep}sis.","Suspected pneumonia with accompanying sepsis."],["Die Anam{ne}se ergab eine Penicil{lin}-Aller{gie}.","The history revealed a penicillin allergy."],["Nach der Opera{tion} bekam der Pati{ent} eine Throm{bo}se.","After the operation the patient developed a thrombosis."]],
 stress:[["Wir vermuten eine Pneumonie.","Pneu·mo·nie",2,"We suspect pneumonia."],["Der Patient hat Diabetes.","Di·a·be·tes",2,"The patient has diabetes."],["Das ist eine Thrombose.","Throm·bo·se",1,"That is a thrombosis."],["Die Diagnose ist noch unklar.","Di·ag·no·se",2,"The diagnosis is still unclear."],["Wir beginnen eine Therapie.","The·ra·pie",2,"We are starting a treatment."],["Sie hat eine Allergie gegen Penicillin.","Al·ler·gie",2,"She is allergic to penicillin."],["Es besteht Verdacht auf Appendizitis.","Ap·pen·di·zi·tis",3,"Appendicitis is suspected."],["Die Fraktur ist nicht verschoben.","Frak·tur",1,"The fracture is not displaced."],["Die Temperatur ist normal.","Tem·pe·ra·tur",3,"The temperature is normal."],["Wir legen einen Katheter.","Ka·the·ter",1,"We are placing a catheter."],["Er hat einen Ikterus.","Ik·te·rus",0,"He is jaundiced."],["Das ist ein Hämatom.","Hä·ma·tom",2,"That is a haematoma."],["Die Arterie ist verschlossen.","Ar·te·ri·e",1,"The artery is occluded."],["Wie geht es Ihrer Familie?","Fa·mi·li·e",1,"How is your family?"],["Wir geben ein Antibiotikum.","An·ti·bi·o·ti·kum",3,"We are giving an antibiotic."],["Sie braucht Insulin.","In·su·lin",2,"She needs insulin."],["Der Patient hat eine Sepsis.","Sep·sis",0,"The patient has sepsis."],["Die Anamnese ist vollständig.","A·nam·ne·se",2,"The history is complete."],["Nach der Operation geht es ihm besser.","O·pe·ra·tion",3,"After the operation he is better."],["Das Ödem ist zurückgegangen.","Ö·dem",1,"The oedema has gone down."]],
 self:[["Betonen Sie Diabetes auf be – nicht wie im Englischen?","Do you stress Diabetes on be – not as in English?"],["Sprechen Sie Familie mit i und e getrennt am Ende?","Do you say the end of Familie with i and e separate?"]],
 meph:["Pneumo{nie}. Nicht „new-MOH-nia“. Der Oberarzt hebt nicht einmal die Augenbraue – die höchste Auszeichnung, die er vergibt.","Pneumonia, the German way. The consultant does not even raise an eyebrow – the highest honour he awards."]},

{id:"lt24",n:24,lv:1,theme:"melodie",dia:"",t:"Satzakzent und Satzmelodie",en:"Sentence stress and intonation",
 rule:["Pro Phrase gibt es einen Hauptakzent, auf der neuen Information, meist spät. Fallend ↘: Aussagen, Aufforderungen, W-Fragen („Wo tut es ↘weh?“). Steigend ↗: Ja/Nein-Fragen („Haben Sie ↗Fieber?“), Rückfragen. Schwebend →: vor einem Komma, in Aufzählungen, vor weil/dass/wenn („Morgens eine →, mittags eine → und abends ↘eine.“). Kontrast verschiebt den Akzent: „Ich habe nach der {Uhr}zeit gefragt, nicht nach dem ↘Datum.“","One main accent per phrase, on the new information, usually late. Falling ↘: statements, commands, W-questions („Wo tut es ↘weh?“). Rising ↗: yes/no questions („Haben Sie ↗Fieber?“), echo questions. Level →: before a comma, in lists, before weil/dass/wenn. Contrast moves the accent: „Ich habe nach der {Uhr}zeit gefragt, nicht nach dem ↘Datum.“"],
 trap:{ar:["Jedes Inhaltswort gleich stark zu betonen klingt im Deutschen gehackt. Ein Gipfel pro Phrase genügt.","Stressing every content word equally sounds choppy in German. One peak per phrase is enough."],
       en:["Steigende W-Fragen und „Uptalk“ in Aussagen klingen in einer Fallvorstellung unsicher. W-Fragen fallen.","Rising W-questions and uptalk in statements sound unsure in a case presentation. W-questions fall."]},
 art:["Lassen Sie die Stimme am Ende einer Aussage deutlich fallen, als würden Sie einen Punkt hörbar machen. Bei Ja/Nein-Fragen heben Sie die letzte betonte Silbe an und bleiben oben. Üben Sie mit der Hand: Sie zeichnet die Melodie in die Luft.","Let the voice fall clearly at the end of a statement, as if making the full stop audible. In yes/no questions lift the last stressed syllable and stay up. Practise with your hand drawing the melody in the air."],
 hint:["Fallvorstellung: „Herr Weber →, vierundsechzig Jahre →, stellte sich mit seit drei Stunden bestehenden →, retrosternalen ↘Schmerzen vor.“","Case presentation melody, level → until the last phrase falls ↘."],
 pairs:[["Sie haben Fieber.","Sie haben Fieber?","","","↘-↗"],["Sie rauchen.","Sie rauchen?","","","↘-↗"],["Das tut weh.","Das tut weh?","","","↘-↗"],["Der Patient ist stabil.","Der Patient ist stabil?","","","↘-↗"],["Sie sind allergisch.","Sie sind allergisch?","","","↘-↗"],["Sie haben gegessen.","Sie haben gegessen?","","","↘-↗"],["Er ist gestürzt.","Er ist gestürzt?","","","↘-↗"],["Sie nehmen Blutverdünner.","Sie nehmen Blutverdünner?","","","↘-↗"],["Die Schmerzen sind stärker.","Die Schmerzen sind stärker?","","","↘-↗"],["Sie wohnen allein.","Sie wohnen allein?","","","↘-↗"]],
 words:["Fieber? ↗","Fieber. ↘","Schmerzen? ↗","Seit wann? ↘","Wo genau? ↘","Allergien? ↗","Morgens → mittags → abends ↘","Bitte noch einmal. ↘"],
 sent:[["Sie haben Schmerzen. – Sie haben Schmerzen? – Seit wann haben Sie Schmerzen?","You have pain. – You have pain? – Since when have you had pain?"],["Nehmen Sie eine morgens, eine mittags und eine abends.","Take one in the morning, one at midday and one in the evening."],["Herr Weber, vierundsechzig Jahre, stellte sich mit seit drei Stunden bestehenden, retrosternalen Schmerzen vor.","Mr Weber, 64, presented with retrosternal pain of three hours' duration."]],
 stress:[["Wo tut es weh?","weh","↘","Where does it hurt?"],["Haben Sie Fieber?","Fieber","↗","Do you have a fever?"],["Sie haben Schmerzen.","Schmerzen","↘","You have pain."],["Sie haben Schmerzen?","Schmerzen","↗","You have pain?"],["Nehmen Sie die Tablette nach dem Essen.","Essen","↘","Take the tablet after the meal."],["Sind Sie gegen etwas allergisch?","allergisch","↗","Are you allergic to anything?"],["Ich habe nach der Uhrzeit gefragt, nicht nach dem Datum.","Uhrzeit","↘","I asked about the time, not the date."],["Nicht das linke Bein – das rechte.","rechte","↘","Not the left leg – the right one."],["Wie heißen Sie?","heißen","↘","What is your name?"],["Haben Sie heute schon gegessen?","gegessen","↗","Have you eaten yet today?"],["Rauchen Sie?","Rauchen","↗","Do you smoke?"],["Wie viele Zigaretten rauchen Sie am Tag?","Zigaretten","↘","How many cigarettes do you smoke a day?"],["Morgens eine, mittags eine und abends eine.","abends","↘","One in the morning, one at midday and one in the evening."],["Der Patient ist stabil.","stabil","↘","The patient is stable."],["Ist der Patient stabil?","stabil","↗","Is the patient stable?"],["Herr Weber, vierundsechzig Jahre, kam mit Brustschmerzen.","Brustschmerzen","↘","Mr Weber, 64, came in with chest pain."],["Das Ergebnis ist da, und es ist gut.","gut","↘","The result is here, and it is good."],["Sie meinen, seit gestern?","gestern","↗","You mean since yesterday?"],["Haben Sie Luftnot oder Brustschmerzen?","Brustschmerzen","↘","Are you short of breath or do you have chest pain?"],["Bitte bleiben Sie liegen.","liegen","↘","Please stay lying down."]],
 self:[["Fällt Ihre Stimme am Ende von „Wo tut es weh?“?","Does your voice fall at the end of 'Wo tut es weh?'?"],["Steigt sie am Ende von „Haben Sie Fieber?“?","Does it rise at the end of 'Haben Sie Fieber?'?"]],
 meph:["Ihre Frage stieg, Ihre Aussage fiel. Endlich klingen Sie wie jemand, der weiß, was er will.","Your question rose, your statement fell. At last you sound like someone who knows what he wants."]},

{id:"lt25",n:25,lv:0,theme:"zahlen",dia:"",t:"Zahlen, Uhrzeiten, Buchstaben – laut und am Ohr",en:"Numbers, times, letters – aloud and by ear",
 rule:["Einer vor Zehnern: vierundfünfzig – die 4 hören Sie zuerst, schreiben sie aber als zweite Ziffer. Am Telefon zwo statt zwei (gegen drei). sechzehn, sechzig, siebzehn, siebzig: ohne -s- und ohne -en-. Dezimalzahlen mit Komma, danach Ziffer für Ziffer: 3,25 = drei Komma zwei fünf. Blutdruck: hundertvierzig zu neunzig. Uhrzeit: halb vier = 3:30, Viertel vor vier = 3:45. Dosis: eins-null-eins, dreimal täglich, alle acht Stunden. Telefonnummern in Paaren oder Ziffer für Ziffer.","Units before tens: vierundfünfzig – you hear the 4 first but write it second. On the phone zwo instead of zwei (against drei). sechzehn, sechzig, siebzehn, siebzig: no -s- and no -en-. Decimals with Komma, then digit by digit: 3,25 = drei Komma zwei fünf. Blood pressure: hundertvierzig zu neunzig. Time: halb vier = 3:30, Viertel vor vier = 3:45. Dosing: eins-null-eins, dreimal täglich, alle acht Stunden. Phone numbers in pairs or digit by digit."],
 trap:{ar:["Arabisch liest Zahlen ebenfalls „Einer und Zehner“ (أربعة وخمسون) – ein Vorteil! Schreiben Sie trotzdem langsam mit.","Arabic also reads numbers 'units and tens' (أربعة وخمسون) – an advantage! Still, write along slowly."],
       en:["Englisch: fifty-four, Deutsch: vierundfünfzig. Buchstaben: E ist nicht „ee“ (das ist I), I ist nicht „eye“, A ist nicht „ay“, V ist „fau“, W ist „weh“, J ist „jott“, Z ist „tsett“.","English: fifty-four, German: four-and-fifty. Letters: E is not 'ee' (that is I), I is not 'eye', A is not 'ay', V is 'fow', W is 'vay', J is 'yot', Z is 'tset'."]},
 art:["Bei -zehn und -zig hören Sie auf das Ende: -zehn hat ein langes e und n, -zig endet auf den ich-Laut. Betont ist der Anfang: {drei}zehn, {drei}ßig. Sprechen Sie Zahlen am Telefon langsamer als alles andere.","For -zehn and -zig listen to the end: -zehn has a long e and n, -zig ends in the ich sound. The stress is on the start: {drei}zehn, {drei}ßig. On the phone say numbers more slowly than anything else."],
 pairs:[["dreizehn","dreißig","ˈdʁaɪ̯tseːn","ˈdʁaɪ̯sɪç","-zehn/-zig"],["vierzehn","vierzig","ˈfɪʁtseːn","ˈfɪʁtsɪç","-zehn/-zig"],["fünfzehn","fünfzig","ˈfʏnftseːn","ˈfʏnftsɪç","-zehn/-zig"],["sechzehn","sechzig","ˈzɛçtseːn","ˈzɛçtsɪç","-zehn/-zig"],["siebzehn","siebzig","ˈziːptseːn","ˈziːptsɪç","-zehn/-zig"],["achtzehn","achtzig","ˈaxtseːn","ˈaxtsɪç","-zehn/-zig"],["neunzehn","neunzig","ˈnɔʏ̯ntseːn","ˈnɔʏ̯ntsɪç","-zehn/-zig"],["Juni","Juli","ˈjuːni","ˈjuːli","Monat"],["vierundfünfzig","fünfundvierzig","ˈfiːɐ̯ʊntˌfʏnftsɪç","ˈfʏnfʊntˌfɪʁtsɪç","Zahlendreher"],["E","I","eː","iː","Buchstabe"],["zwei","drei","tsvaɪ̯","dʁaɪ̯","zwei-drei"],["halb vier","vier Uhr dreißig","","","Uhrzeit"]],
 words:["zwo","dreißig","sechzig","siebzehn","Komma","Viertel","halb","Eszett"],
 sent:[["Ismail – I wie Ida, S wie Samuel, M wie Martha, A wie Anton, I wie Ida, L wie Ludwig.","Spelling a name with the traditional spelling alphabet."],["Der Blutdruck war hundertfünfundsechzig zu fünfundneunzig, das Kalium drei Komma zwei.","The blood pressure was 165 over 95, the potassium 3.2."],["Meine Durchwahl ist zwo-vier-sieben-null.","My extension is 2-4-7-0."]],
 abc:[["A","aː","Anton","Aachen"],["B","beː","Berta","Berlin"],["C","tseː","Cäsar","Chemnitz"],["D","deː","Dora","Düsseldorf"],["E","eː","Emil","Essen"],["F","ɛf","Friedrich","Frankfurt"],["G","ɡeː","Gustav","Goslar"],["H","haː","Heinrich","Hamburg"],["I","iː","Ida","Ingelheim"],["J","jɔt","Julius","Jena"],["K","kaː","Kaufmann","Köln"],["L","ɛl","Ludwig","Leipzig"],["M","ɛm","Martha","München"],["N","ɛn","Nordpol","Nürnberg"],["O","oː","Otto","Offenbach"],["P","peː","Paula","Potsdam"],["Q","kuː","Quelle","Quickborn"],["R","ɛʁ","Richard","Rostock"],["S","ɛs","Samuel / Siegfried","Salzwedel"],["T","teː","Theodor","Tübingen"],["U","uː","Ulrich","Unna"],["V","faʊ̯","Viktor","Völklingen"],["W","veː","Wilhelm","Wuppertal"],["X","ɪks","Xanthippe","Xanten"],["Y","ˈʏpsilɔn","Ypsilon","Ypsilon"],["Z","tsɛt","Zacharias / Zeppelin","Zwickau"],["Ä","ɛː","Ärger","Umlaut-A"],["Ö","øː","Ökonom","Umlaut-O"],["Ü","yː","Übermut","Umlaut-U"],["ß","ɛsˈtsɛt","Eszett","Eszett"]],
 extra:["Zwei Buchstabiertafeln sind in Gebrauch: die traditionelle (Anton, Berta, Cäsar … – viele ältere Kolleginnen und Kollegen) und die Städtetafel nach DIN 5009 (Aachen, Berlin, Chemnitz …). Verstehen Sie beide; sprechen Sie eine davon sicher.","Two spelling alphabets are in use: the traditional one (Anton, Berta, Cäsar … – many older colleagues) and the city alphabet of DIN 5009 (Aachen, Berlin, Chemnitz …). Understand both; use one of them confidently."],
 self:[["Unterscheiden Sie beim Sprechen deutlich -zehn und -zig?","Do you clearly distinguish -zehn and -zig when speaking?"],["Buchstabieren Sie Ihren Namen ohne englische Buchstabennamen?","Can you spell your name without English letter names?"]],
 meph:["Fünfzehn, nicht fünfzig. Eine Null weniger Ärger – für Sie und für die Apotheke.","Fifteen, not fifty. One zero less trouble – for you and for the pharmacy."]}
];

// Shadowing passages (Schattenstudio) — used when no l6 transcript or lesson dialogue fits the learner's level. [de,en] per line.
var LAUT_SCHATTEN=[
 {id:"ls01",lv:0,theme:"klinik",t:"Aufnahme in der Notaufnahme",en:"Admission in the ED",lines:[["Guten Tag. Ich bin der Arzt in der Notaufnahme.","Hello. I am the doctor in the emergency department."],["Wie heißen Sie, bitte?","What is your name, please?"],["Wann sind Sie geboren?","When were you born?"],["Was ist passiert?","What happened?"],["Wo tut es weh?","Where does it hurt?"],["Seit wann haben Sie die Schmerzen?","Since when have you had the pain?"]]},
 {id:"ls02",lv:0,theme:"alltag",t:"Beim Bäcker",en:"At the bakery",lines:[["Guten Morgen! Zwei Brötchen, bitte.","Good morning! Two rolls, please."],["Sonst noch etwas?","Anything else?"],["Ja, ein Stück Apfelkuchen.","Yes, a piece of apple cake."],["Das macht drei Euro fünfzig.","That comes to three euros fifty."],["Hier, bitte. Stimmt so.","Here you are. Keep the change."],["Danke, einen schönen Tag noch!","Thank you, have a nice day!"]]},
 {id:"ls03",lv:1,theme:"klinik",t:"Schmerzen genau erfragen",en:"Asking about pain",lines:[["Bitte zeigen Sie mir, wo es wehtut.","Please show me where it hurts."],["Ist der Schmerz stechend, dumpf oder brennend?","Is the pain stabbing, dull or burning?"],["Strahlt der Schmerz in den Arm oder in den Rücken aus?","Does the pain radiate into the arm or the back?"],["Auf einer Skala von null bis zehn: Wie stark ist er jetzt?","On a scale from zero to ten: how strong is it now?"],["Haben Sie schon ein Schmerzmittel genommen?","Have you already taken a painkiller?"]]},
 {id:"ls04",lv:1,theme:"alltag",t:"Anruf beim Vermieter",en:"Calling the landlord",lines:[["Guten Tag, ich wohne in der Hauptstraße zwölf, im dritten Stock.","Hello, I live at Hauptstraße 12, on the third floor."],["Bei mir funktioniert die Heizung seit gestern nicht.","My heating has not been working since yesterday."],["Können Sie heute noch jemanden schicken?","Can you send someone today?"],["Ich bin ab siebzehn Uhr zu Hause.","I am at home from five p.m."],["Vielen Dank, dann bis später.","Thank you very much, see you later then."]]},
 {id:"ls05",lv:1,theme:"alltag",t:"Ummelden im Bürgeramt",en:"Registering a new address",lines:[["Ich möchte mich ummelden; ich bin vor zwei Wochen umgezogen.","I would like to register my new address; I moved two weeks ago."],["Hier sind mein Pass und die Wohnungsgeberbestätigung.","Here are my passport and the landlord's confirmation."],["Brauchen Sie sonst noch etwas von mir?","Do you need anything else from me?"],["Wann bekomme ich die Meldebescheinigung?","When will I get the registration certificate?"]]},
 {id:"ls06",lv:2,theme:"klinik",t:"Blutabnahme erklären",en:"Explaining a blood draw",lines:[["Ich nehme Ihnen jetzt Blut ab, das dauert nur einen Moment.","I am going to take some blood now; it only takes a moment."],["Machen Sie bitte eine Faust und atmen Sie ruhig weiter.","Please make a fist and keep breathing calmly."],["Es piekst kurz – so, schon vorbei.","A short prick – there, all done."],["Drücken Sie den Tupfer bitte zwei Minuten fest auf die Stelle.","Please press the swab firmly on the spot for two minutes."],["Die Ergebnisse haben wir in etwa einer Stunde.","We will have the results in about an hour."]]},
 {id:"ls07",lv:2,theme:"klinik",t:"Kurze Übergabe",en:"Short handover",lines:[["Ich übergebe Ihnen Herrn Keller aus Zimmer zwölf.","I am handing over Mr Keller from room twelve."],["Er ist achtundsiebzig Jahre alt und kam heute Morgen mit Luftnot.","He is seventy-eight and came in this morning short of breath."],["Bekannt ist eine Herzinsuffizienz.","He has known heart failure."],["Nach Furosemid liegt die Sättigung jetzt bei vierundneunzig Prozent.","After furosemide the saturation is now ninety-four per cent."],["Bitte kontrollieren Sie in zwei Stunden noch einmal die Elektrolyte.","Please check the electrolytes again in two hours."],["Die Angehörigen sind informiert.","The relatives have been informed."]]},
 {id:"ls08",lv:2,theme:"klinik",t:"Nachtdienst: Rückruf an die Pflege",en:"Night shift: calling the nurse back",lines:[["Danke für den Anruf. Wie hoch ist der Blutdruck jetzt?","Thanks for calling. How high is the blood pressure now?"],["Hat der Patient Kopfschmerzen oder Sehstörungen?","Does the patient have a headache or visual disturbances?"],["Bitte messen Sie in einer halben Stunde noch einmal.","Please measure again in half an hour."],["Wenn der Wert über hundertachtzig bleibt, rufen Sie mich bitte sofort an.","If the value stays above one hundred and eighty, please call me immediately."],["Ich komme in zehn Minuten vorbei und sehe mir den Patienten an.","I will come by in ten minutes and look at the patient."]]},
 {id:"ls09",lv:3,theme:"klinik",t:"Fallvorstellung",en:"Case presentation",lines:[["Ich stelle Ihnen Herrn Weber vor, vierundsechzig Jahre alt.","Let me present Mr Weber, sixty-four years old."],["Er stellte sich mit seit drei Stunden bestehenden, retrosternalen Schmerzen vor.","He presented with retrosternal pain of three hours' duration."],["Die Schmerzen strahlen in den linken Arm aus und werden von Übelkeit begleitet.","The pain radiates into the left arm and is accompanied by nausea."],["Im EKG zeigen sich ST-Hebungen in den inferioren Ableitungen.","The ECG shows ST elevation in the inferior leads."],["Wir gehen von einem Hinterwandinfarkt aus und haben das Herzkatheterlabor bereits informiert.","We assume an inferior myocardial infarction and have already informed the cath lab."]]},
 {id:"ls10",lv:3,theme:"pruefung",t:"Meinung äußern (Goethe B2)",en:"Giving an opinion",lines:[["Ich bin der Meinung, dass Homeoffice viele Vorteile hat.","I am of the opinion that working from home has many advantages."],["Man spart Zeit, weil der Weg zur Arbeit wegfällt.","You save time because there is no commute."],["Andererseits fehlt oft der direkte Kontakt zu den Kollegen.","On the other hand, direct contact with colleagues is often missing."],["Für Berufsanfänger halte ich das sogar für einen Nachteil.","For people starting their careers I even consider that a disadvantage."],["Insgesamt würde ich eine Mischung aus beidem vorschlagen.","Overall I would suggest a mix of both."]]},
 {id:"ls11",lv:4,theme:"klinik",t:"Arzt-Arzt-Gespräch",en:"Doctor-to-doctor talk",lines:[["Aufgrund der Klinik und der Laborbefunde besteht der dringende Verdacht auf eine Lungenembolie.","Given the clinical picture and the lab results, a pulmonary embolism is strongly suspected."],["Differenzialdiagnostisch kommen ein akutes Koronarsyndrom sowie eine Pneumonie in Betracht.","Differential diagnoses include an acute coronary syndrome and pneumonia."],["Wir haben eine CT-Angiographie angemeldet und bereits mit der Antikoagulation begonnen.","We have requested a CT angiogram and have already started anticoagulation."],["Sollte sich der Verdacht bestätigen, verlegen wir den Patienten auf die Überwachungsstation.","If the suspicion is confirmed, we will transfer the patient to the monitoring unit."]]},
 {id:"ls12",lv:4,theme:"klinik",t:"Aufklärung über Risiken",en:"Explaining risks",lines:[["Bevor wir den Eingriff durchführen, möchte ich Sie über die möglichen Risiken aufklären.","Before we carry out the procedure, I would like to explain the possible risks."],["In seltenen Fällen kann es zu Blutungen oder Infektionen kommen.","In rare cases bleeding or infection can occur."],["Sehr selten werden benachbarte Strukturen verletzt.","Very rarely, neighbouring structures are injured."],["Haben Sie dazu noch Fragen, oder ist etwas unklar geblieben?","Do you have any questions, or is anything still unclear?"],["Dann bitte ich Sie, hier zu unterschreiben.","Then I would ask you to sign here."]]}
];

// Weekly read-aloud texts (Vorlesen): about 60 seconds at a calm pace. Used when l6 offers no current text at the learner's level.
var LAUT_VORLESEN=[
 {id:"lv01",lv:0,theme:"alltag",t:"Mein Tag",en:"A doctor describes his working day.",text:"Ich heiße Sami und ich bin Arzt. Ich stehe jeden Tag um sechs Uhr auf. Zuerst trinke ich einen Kaffee, dann fahre ich mit dem Bus zur Arbeit. Das Krankenhaus ist groß und hell. Ich arbeite in der Notaufnahme. Dort ist immer viel los. Viele Patienten haben Schmerzen, Fieber oder Husten. Ich frage: „Wo tut es weh?“ und „Seit wann haben Sie das?“ Am Mittag esse ich in der Kantine. Am Abend gehe ich oft spazieren, oder ich lerne Deutsch. Um zehn Uhr gehe ich ins Bett. Morgen ist wieder ein langer Tag."},
 {id:"lv02",lv:0,theme:"alltag",t:"Meine Wohnung",en:"A small flat and a friendly neighbour.",text:"Meine Wohnung ist nicht groß, aber sie ist schön. Sie hat zwei Zimmer, eine kleine Küche und ein Bad. Im Wohnzimmer stehen ein Sofa, ein Tisch und ein Regal mit Büchern. Das Schlafzimmer ist ruhig, denn das Fenster geht zum Hof. Die Küche ist neu. Ich koche gern, am liebsten Suppe oder Reis mit Gemüse. Die Wohnung liegt im dritten Stock. Leider gibt es keinen Aufzug. Mein Nachbar heißt Herr Becker. Er ist alt und sehr freundlich. Manchmal trinken wir zusammen Tee. Ich wohne gern hier."},
 {id:"lv03",lv:1,theme:"alltag",t:"Ein Wochenende in Heidelberg",en:"A sunny Saturday by the river and in the old town.",text:"Am Samstag war das Wetter endlich schön. Ich bin früh aufgestanden und mit dem Fahrrad an den Neckar gefahren. Dort war es noch ruhig, nur ein paar Jogger waren unterwegs. Später bin ich in die Altstadt gegangen und habe mir das Schloss angesehen. Der Weg nach oben ist steil, aber die Aussicht ist wunderbar. Am Nachmittag habe ich eine Kollegin getroffen. Wir haben Kuchen gegessen und über die Arbeit gesprochen. Sie hat mir erzählt, dass sie auch aus dem Ausland kommt und am Anfang große Probleme mit der Sprache hatte. Am Sonntag habe ich nur gelesen und mich ausgeruht."},
 {id:"lv04",lv:1,theme:"klinik",t:"Beim Hausarzt",en:"A patient with a cold visits her GP.",text:"Frau Klein hat seit drei Tagen Halsschmerzen und Fieber. Am Montag geht sie zum Hausarzt. Im Wartezimmer sitzen schon viele Leute, deshalb muss sie fast eine Stunde warten. Dann ruft die Arzthelferin ihren Namen. Der Arzt hört die Lunge ab und schaut in den Hals. „Das ist eine Erkältung“, sagt er, „aber keine Grippe.“ Er schreibt sie für drei Tage krank und gibt ihr ein Rezept für Lutschtabletten. Sie soll viel trinken und sich ausruhen. Wenn das Fieber über neununddreißig Grad steigt, soll sie wiederkommen. Auf dem Heimweg geht Frau Klein noch in die Apotheke."},
 {id:"lv05",lv:2,theme:"klinik",t:"Der erste Nachtdienst",en:"A foreign doctor's first night shift in German.",text:"Mein erster Nachtdienst begann um einundzwanzig Uhr. Ich war nervös, obwohl ich schon viele Jahre als Arzt gearbeitet hatte. Die Kollegin vom Spätdienst übergab mir sieben Patienten und erklärte mir, worauf ich achten sollte. Gegen Mitternacht kam ein älterer Mann mit Atemnot. Während ich ihn untersuchte, versuchte ich, ruhig und deutlich zu sprechen. Seine Tochter beantwortete die meisten Fragen, weil er kaum Luft bekam. Nach der Behandlung ging es ihm deutlich besser. Um vier Uhr morgens trank ich meinen ersten Kaffee und merkte, dass ich die ganze Nacht Deutsch gesprochen hatte – ohne ein einziges Mal ins Englische zu wechseln."},
 {id:"lv06",lv:2,theme:"alltag",t:"Mülltrennung",en:"How rubbish is sorted in Germany.",text:"Wer in Deutschland wohnt, lernt schnell: Müll ist nicht einfach Müll. In den meisten Häusern gibt es mehrere Tonnen; die Farben können je nach Stadt etwas anders sein. Meistens kommt in die blaue Tonne Papier, in die gelbe Tonne oder den gelben Sack kommen Verpackungen aus Plastik und Metall. Bioabfall, also zum Beispiel Obst- und Gemüsereste, gehört in die braune Tonne. Alles andere landet im Restmüll. Glasflaschen bringt man zum Container, getrennt nach Weiß-, Braun- und Grünglas. Für viele Flaschen bekommt man außerdem Pfand zurück, wenn man sie in den Supermarkt bringt. Am Anfang wirkt das kompliziert, aber nach ein paar Wochen macht man es automatisch."},
 {id:"lv07",lv:3,theme:"gesellschaft",t:"Fachkräftemangel im Krankenhaus",en:"The shortage of skilled staff in German hospitals.",text:"Der Mangel an Fachkräften ist in deutschen Krankenhäusern seit Jahren ein zentrales Thema. Besonders in der Pflege, aber auch im ärztlichen Dienst bleiben viele Stellen unbesetzt. Kliniken versuchen deshalb verstärkt, Personal aus dem Ausland zu gewinnen. Für die Betroffenen ist der Weg allerdings oft lang: Abschlüsse müssen anerkannt, Sprachprüfungen bestanden und zahlreiche Unterlagen eingereicht werden. Kritiker bemängeln, die Verfahren seien zu bürokratisch und dauerten zu lange. Befürworter betonen hingegen, dass hohe Standards die Patientensicherheit gewährleisten. Fest steht, dass gute Sprachkenntnisse nicht nur für die Prüfung, sondern vor allem für die tägliche Zusammenarbeit im Team entscheidend sind."},
 {id:"lv08",lv:3,theme:"gesundheit",t:"Schlaf und Schichtarbeit",en:"How shift work affects sleep, and what helps.",text:"Schichtarbeit bringt den natürlichen Rhythmus des Körpers durcheinander. Wer nachts arbeitet, muss tagsüber schlafen, obwohl Licht und Lärm genau das erschweren. Studien zeigen, dass Beschäftigte im Schichtdienst häufiger unter Schlafstörungen, Konzentrationsproblemen und Magen-Darm-Beschwerden leiden. Experten empfehlen daher, das Schlafzimmer konsequent abzudunkeln, feste Ruhezeiten einzuhalten und gegen Ende des Nachtdienstes auf Kaffee zu verzichten. Auch ein kurzer Schlaf vor einer Nachtschicht kann helfen. Entscheidend sei jedoch, dass Arbeitgeber Dienstpläne möglichst vorausschauend gestalten, damit die Mitarbeitenden ihr Privatleben planen und sich ausreichend erholen können."},
 {id:"lv09",lv:4,theme:"recht",t:"Die ärztliche Aufklärungspflicht",en:"The duty to inform a patient before a procedure.",text:"Vor einem medizinischen Eingriff ist die Ärztin oder der Arzt verpflichtet, den Patienten umfassend aufzuklären. Die Aufklärung muss rechtzeitig erfolgen, damit der Patient genügend Zeit hat, seine Entscheidung abzuwägen. Sie umfasst Art, Umfang und Durchführung der Maßnahme, die zu erwartenden Folgen und Risiken sowie mögliche Behandlungsalternativen. Entscheidend ist, dass das Gespräch in einer für den Patienten verständlichen Sprache geführt wird; das bloße Aushändigen eines Formulars genügt nicht. Fehlt eine wirksame Einwilligung, kann selbst ein fachgerecht durchgeführter Eingriff rechtlich als Körperverletzung gewertet werden. Gerade für Ärztinnen und Ärzte aus dem Ausland zeigt dies, wie eng Sprachkompetenz und Patientensicherheit miteinander verknüpft sind."},
 {id:"lv10",lv:4,theme:"literatur",t:"Faust: Habe nun, ach!",en:"Goethe, Faust I, the opening of the night scene (public domain). Keep the line breaks: pause at each.",verse:true,text:"Habe nun, ach! Philosophie,\nJuristerei und Medizin,\nUnd leider auch Theologie\nDurchaus studiert, mit heißem Bemühn.\nDa steh ich nun, ich armer Tor!\nUnd bin so klug als wie zuvor;\nHeiße Magister, heiße Doktor gar\nUnd ziehe schon an die zehen Jahr\nHerauf, herab und quer und krumm\nMeine Schüler an der Nase herum –\nUnd sehe, dass wir nichts wissen können!\nDas will mir schier das Herz verbrennen."}
];

// Line list for l8 (audio build tier d). Every string a model voice may have to speak in the Lautschule and the Schattenstudio.
// who:"Modell" = neutral model voice. Text is the display text with stress braces and arrows removed (l8 applies ttsNorm).
var LAUT_AUDIO=function(){const out=[],seen={};const clean=t=>String(t).replace(/[{}|]/g,"").replace(/[↘↗→]/g,"").replace(/\s+/g," ").trim();
  const add=(t,kind)=>{t=clean(t);if(!t||seen[t])return;seen[t]=1;out.push({text:t,who:"Modell",kind})};
  LAUT.forEach(u=>{u.pairs.forEach(p=>{if(p[5]==="h")return;add(p[6]||p[0],"paar");add(p[7]||p[1],"paar")});u.words.forEach(w=>add(w,"wort"));u.sent.forEach(s=>add(s[0],"satz"));(u.stress||[]).forEach(s=>add(s[0],"akzent"))});
  LAUT_SCHATTEN.forEach(s=>s.lines.forEach(l=>add(l[0],"schatten")));return out};

